NAME = 'GerGruenewald: 1924 Grünewaldbibel'
BOOK = 'II Samuel'

CHAPTERS = {
    1: {
        1: 'Und erst nach Sauls Tod war David vom Sieg über die Amalekiter heimgekehrt; er weilte nun zwei Tage in Siklag.',
        2: 'Da kam am dritten Tag ein Mann aus dem Lager, von Saul her, seine Kleider zerrissen und Staub auf dem Kopfe. Als er zu David kam, neigte er sich bis zur Erde und verbeugte sich.',
        3: 'Da sprach David zu ihm: "Woher kommst du?" Er sprach: "Ich bin aus Israels Lager entronnen."',
        4: 'Da sprach David zu ihm: "Wie ging es? Berichte mir!" Er sprach: "Das Kriegsvolk ist aus der Schlacht geflohen, und viele aus dem Volke sind gefallen, so daß sie starben und tot sind. Auch Saul und sein Sohn Jonatan sind tot."',
        5: 'Da sprach David zu dem jungen Manne, der ihm die Botschaft brachte: "Wie weißt du, daß Saul und sein Sohn Jonatan tot sind?"',
        6: 'Da sprach der junge Mann, der ihm die Botschaft brachte: "Ich bin zufällig auf das Gebirge des Gilboa gekommen. Da hatte sich Saul auf seinen Speer gelehnt. Die Wagen aber und die Reiterei waren schon dicht hinter ihm her.',
        7: "Da wandte er sich um und sah mich. Er rief mich an, und ich sprach: 'Da bin ich!'",
        8: "Dann sprach er zu mir: 'Wer bist du?' Ich sprach zu ihm: 'Ich bin ein Amalekiter.'",
        9: "Da sprach er zu mir: 'Tritt herzu und gib mir den Todesstoß! Mich befällt Ohnmacht; denn ich lebe noch.'",
        10: 'Da trat ich zu ihm und gab ihm den Todesstoß. Denn ich wußte, daß er seinen Sturz nicht überleben würde. Ich nahm das Diadem auf seinem Haupte und die Spange an seinem Arm und bringe sie hier meinem Herrn."',
        11: 'Da packte David seine Gewänder und zerriß sie, ebenso alle Männer bei ihm.',
        12: 'Und sie trauerten, weinten und fasteten bis zum Abend um Saul und seinen Sohn Jonatan und um das Volk des Herrn und um das Haus Israel, daß sie durch das Schwert gefallen waren.',
        13: 'Dann sprach David zu dem jungen Mann, der ihm die Meldung brachte: "Woher bist du?" Er sprach: "Ich bin der Sohn eines zugewanderten Amalekiters."',
        14: 'Da sprach David zu ihm: "Wie? Du hast dich nicht gescheut, Hand anzulegen, um den Gesalbten des Herrn umzubringen?"',
        15: 'Dann rief David einen seiner Knechte und sprach: "Her! Stoß ihn nieder!" Da schlug er ihn nieder, so daß er starb.',
        16: 'Und David sprach zu ihm: "Dein Blut über dein Haupt! Dein eigener Mund klagt dich an; du sagtest: \'ich habe den Gesalbten des Herrn getötet.\'"',
        17: 'Dann dichtete David dieses Klagelied auf Saul und seinen Sohn Jonatan:',
        18: 'Er sprach: "Man lehre es die Söhne Judas auf der Zither!" Aufgezeichnet ist es im "Buche des Richtigen":',
        19: '"Der Adel liegt, o Israel, erschlagen dort auf deinen Höhen. Wie sind gestürzt die Helden!',
        20: "Verkündet's nicht zu Gat! Bringt nicht die Botschaft in die Gassen Askalons, daß der Philister Töchter sich nicht freuen, nicht jubeln dieser Unbeschnittenen Töchter!",
        21: 'Ihr Berge Gilboas! Nicht Tau, nicht Regen falle mehr auf euch und nicht auf die Gefilde Dotains! Dort ward des Helden Schild zuschanden, der Schild des zwiefach ölgesalbten Saul!',
        22: 'Vor der unreinen Sippe, vor Kriegsvolk ist nie der Bogen Jonatans zurückgewichen. Nie kehrte leer zurück das Schwert des Saul.',
        23: 'Saul und Jonatan, die Lieben und die Holden, im Leben und im Tode sind sie nicht getrennt, einst schneller als die Adler und stärker als die Löwen.',
        24: 'Ihr Töchter Israels! Weint über Saul, der euch in Purpur lieblich kleidete, Der Goldschmuck eurer Kleidung gab!',
        25: 'Wie sind die Helden hingestürzt im Kampfgedränge! Auf deinen Höhen wurde Jonatan erschlagen.',
        26: 'Mein Bruder Jonatan! So leid ist mir um dich. Du warst mir gar so hold. Noch wundersamer war mir',
        27: 'Wie sind die Helden hingestürzt! Des Krieges Waffen schwanden hin."',
    },
    2: {
        1: 'Als David hernach den Herrn befragte: "Darf ich in eine der Städte Judas ziehen?" sprach der Herr zu ihm: "Ja!" Da fragte David: "Wohin soll ich ziehen?" Er sprach: "Nach Hebron."',
        2: 'David zog nun dorthin, ebenso seine beiden Frauen, die Jezreelitin Achinoam und die Karmelitin Abigail, Nabals Witwe.',
        3: 'Auch seine Mannen, die bei ihm waren, brachte David hin, jeden mit seiner Familie. Und so saßen sie in Hebrons Städten.',
        4: 'Da kamen die Männer Judas und salbten dort David zum König über das Haus Juda. Da meldete man David: "Die Männer von Jabes in Gilead haben Saul begraben."',
        5: 'Da sandte David Boten zu den Männern von Jabes in Gilead und ließ ihnen sagen: "Seid vom Herrn gesegnet, die ihr diese Liebe eurem Herrn Saul erwiesen und ihn begraben habt!',
        6: 'Nun möge auch der Herr euch Liebe und Treue erweisen, und auch ich will euch Gutes tun, wie ihr getan habt.',
        7: 'Nun seid mutig! Und seid tapfere Leute! Weil euer Herr Saul starb, so salbten mich die vom Hause Juda zum König über sich."',
        8: 'Abner, Ners Sohn und Sauls Feldherr, hatte nun Sauls Sohn Isboset mitgenommen; dann brachte er ihn nach Machanaim hinüber.',
        9: 'Und er machte ihn zum König über Gilead und über Basan sowie über Jezreel, Ephraim, Benjamin und das sonstige Israel.',
        10: 'Vierzig Jahre alt war Sauls Sohn Isboset, als er König über Israel ward, und zwei Jahre hat er regiert. Nur das Haus Juda hielt zu David.',
        11: 'Die Zeit, die David in Hebron König über das Haus Juda war, betrug sieben Jahre und sechs Monate.',
        12: 'Von Machanaim nun zog Abner, Ners Sohn, mit den Knechten des Saulsohnes Isboset nach Gibeon.',
        13: 'Auch Serujas Sohn Joab zog mit den Knechten Davids aus. Sie trafen sich nun an dem Teiche von Gibeon. Die einen saßen diesseits, die anderen jenseits des Teiches.',
        14: 'Da sprach Abner zu Joab: "Mögen doch die Knechte aufstehen und im Kampfspiel vor uns streiten!" Joab sprach: "Ja!"',
        15: 'Da machten sie sich auf und rückten abgezählt aus zwölf von Benjamin und von den Mannen des Saulsohnes Isboset und zwölf von Davids Knechten.',
        16: 'Da packten sie einander am Kopf und stießen einander das Schwert in die Seite. So fielen sie allzumal. Man hieß jenen Ort: "Feld der Felsmuscheln". Er liegt bei Gibeon.',
        17: 'Da ward der Kampf an jenem Tage immer ernster. Abner und die Leute Israels aber wurden von Davids Knechten geschlagen.',
        18: 'Nun waren dort die drei Serujasöhne, Joab, Abisai und Asahel. Asahel war leichtfüßiger als eine der Gazellen auf der Flur.',
        19: 'Und Asahel verfolgte den Abner. Er bog weder nach rechts noch nach links ab hinter Abner her.',
        20: 'Da wandte sich Abner und sprach: "Bist du es, Asahel?" Er sprach: "Jawohl, ich bin es."',
        21: 'Da sprach Abner zu ihm: "Bieg nach rechts oder nach links ab! Greif dir einen der Knechte und nimm dir seine Rüstung!" Aber Asahel wollte nicht von ihm lassen.',
        22: 'Da sprach Abner nochmals zu Asahel: "Geh hinter mir weg! Wozu soll ich dich zu Boden schlagen? Wie könnte ich dann deinem Bruder Joab unter die Augen kommen?"',
        23: 'Er aber weigerte sich, abzulassen. Da stieß ihm Abner die Lanzenspitze in den Leib, daß der Speer rückwärts herauskam. Er fiel dort hin und starb auf der Stelle. Wer an die Stelle gelangte, wo Asahel gefallen und gestorben war, machte Halt.',
        24: 'Joab und Abisai verfolgten noch Abner. Als die Sonne unterging, waren sie bis zum Eckhügel bei der Quelle gekommen, an der Straße zur Wüste von Gibeon.',
        25: 'Da sammelten sich die Benjaminiten hinter Abner. Sie bildeten eine Schar und stellten sich auf den Gipfel eines Hügels.',
        26: 'Da rief Abner dem Joab zu und sprach: "Soll denn ewig das Schwert fressen? Weißt du nicht, daß schließlich Bitteres kommt? Wie lange willst du dem Volke nicht sagen, es soll von seinen Brüdern lassen?"',
        27: 'Da sprach Joab: "Beim Leben Gottes! Hättest du nur geredet, dann hätte das Volk schon am Morgen von seinen Brüdern abgelassen."',
        28: 'Dann stieß Joab in das Horn. Und alles machte halt, und sie verfolgten Israel nicht mehr und kämpften nicht weiter.',
        29: 'Abner und seine Leute aber waren jene ganze Nacht hindurch nach der Steppe gezogen. Dann setzten sie über den Jordan, durchzogen die ganze Schlucht und kamen nach Machanaim.',
        30: 'Joab aber hatte von Abner abgelassen; er sammelte nun das ganze Volk. Da fehlten von Davids Knechten neunzehn Mann und Asahel.',
        31: 'Die Knechte Davids aber hatten eine Anzahl von den Benjaminiten und von den 300 Manneu Abners erschlagen: 60 Mann nämlich waren gefallen.',
        32: 'Sie hoben nun Asahel auf und begruben ihn in seines Vaters Grab zu Bethlehem. Dann marschierten Joab und seine Leute die ganze Nacht. Bei Tagesanbruch kamen sie in Hebron an.',
    },
    3: {
        1: 'Lange währte der Krieg zwischen Sauls Haus und dem Hause Davids. David aber wurde immer stärker, Sauls Haus immer schwächer.',
        2: 'Zu Hebron wurden David Söhne geboren. Sein Erstgeborener war Amnon, der Jezreelitin Achinoam Sohn.',
        3: 'Sein nächster war Kilab, der Sohn der Karmelitin Abigail, der Witwe des Nabal. Der dritte war Absalom, der Sohn Maakas, der Tochter Talmais, des Königs von Gesur.',
        4: 'Der vierte war Adonia, Chaggits Sohn. Der fünfte war Sephatia, Abitals Sohn.',
        5: 'Der sechste war Jitream, der Sohn von Davids Weib Egla. Diese wurden David zu Hebron geboren.',
        6: 'Solange der Krieg zwischen Sauls Haus und dem Davidshause währte, hielt Abner fest zum Hause Sauls.',
        7: 'Saul aber hatte ein Nebenweib gehabt, Ajas Tochter namens Nispa. Da sprach Isboset zu Abner: "Warum hast du meines Vaters Nebenweib geheiratet?"',
        8: 'Da zürnte Abner ob der Worte des Isboset und sprach: "Bin ich ein Hundskopf, der es mit Juda hält? Heute noch erweise ich Gunst dem Hause deines Vaters Saul, seinen Brüdern und Freunden. Ich habe dich nicht in Davids Hand fallen lassen. Und du wirfst mir heute dieses Weib vor?',
        9: 'So tue Gott dem Abner, und so mache er es ihm! Was der Herr dem David zugeschworen, das tue ich für ihn.',
        10: 'Ich entreiße das Königtum dem Hause des Saul und errichte Davids Thron über Israel und Juda von Dan bis Beerseba."',
        11: 'Da konnte er Abner kein Wort mehr erwidern, aus Furcht vor ihm.',
        12: 'Abner schickte aber auf der Stelle Boten an David mit der Botschaft: "Wes ist das Land?" Damit sagte er: "Verbünde dich mit mir! Dann ist meine Hand mit dir, und ich führe dir ganz Israel zu."',
        13: 'Jener sprach: "Gut! Ich verbünde mich mit dir. Nur das eine fordere ich von dir: Du siehst nicht mein Antlitz, außer du bringst Sauls Tochter Mikal mit, wenn du herkommst, mein Antlitz zu sehen."',
        14: 'David sandte auch Boten an Sauls Sohn Isboset und ließ sagen: "Gib mir mein Weib Mikal heraus, die ich mir um hundert Philisterglieder gefreit habe!"',
        15: 'Isboset schickte nun hin und ließ sie von ihrem Manne Paltiel, dem Sohn des Lais, holen.',
        16: 'Ihr Mann aber ging mit ihr und folgte ihr beständig weinend bis Bachurim. Da sprach Abner zu ihm: "Auf! Kehre um!" Da kehrte er um.',
        17: 'Abners Wort aber erging an die Ältesten Israels: "Früher schon habt ihr David zum König über euch begehrt.',
        18: 'Nun führt es aus! Denn der Herr hat von David gesprochen: \'Durch David, meinen Knecht, rette ich mein Volk Israel aus der Philister Hand und aus der Hand all seiner anderen Feinde.\'"',
        19: 'Ebenso sprach Abner zu Benjamin. Dann ging Abner, um es auch David in Hebron zu melden, was Israel und das ganze Benjaminhaus wünschten.',
        20: 'So kam Abner zu David nach Hebron mit zwanzig Mann. Da gab David dem Abner und den Mannen bei ihm ein Gastmahl.',
        21: 'Abner sprach nun zu David: "Ich will mich aufmachen und hingehen zu meinem Herrn, dem König, und ganz Israel entbieten, daß sie sich mit dir verbünden. Dann kannst du König sein, wie du nur wünschest." Da entließ David den Abner. Und er ging in Frieden.',
        22: 'Da kamen Davids Leute mit Joab von einem Streifzug und brachten reiche Beute mit. Abner aber war nicht mehr bei David in Hebron. Denn er hatte ihn entlassen, und er war in Frieden gegangen.',
        23: 'Joab und die ganze Schar bei ihm war nun heimgekommen. Da meldete man Joab: "Ners Sohn Abner ist zum König gekommen; er aber ließ ihn ziehen, und so ging er in Frieden."',
        24: 'Da kam Joab zum König und sprach: "Was hast du getan? Abner ist ja zu dir gekommen. Warum hast du ihn fortziehen lassen, daß er gehen konnte?',
        25: 'Du kennst doch Abner, Ners Sohn. Er ist nur gekommen, dich zu hintergehen, dein Tun und Lassen zu erkunden und alles, was du tust, auszuspähen."',
        26: 'Und Joab ging von David weg und sandte Boten hinter Abner her. Sie holten ihn vom Brunnen der Herberge zurück. David aber hatte nichts davon gewußt.',
        27: 'So kam Abner wieder nach Hebron. Da nahm ihn Joab inmitten des Tores beiseite, mit ihm ungestört zu reden. Er stach ihn aber dort in den Leib. So starb er für das Blut seines Bruders Asahel.',
        28: 'David hörte es nachher und sprach: "Ich und mein Königtum sind vor dem Herrn allzeit unschuldig am Blute Abners, des Nersohnes.',
        29: 'Es falle auf Joabs Haupt und auf sein ganzes Vaterhaus! Niemals fehle es im Hause Joabs an Flüssigen und Aussätzigen, an Spindelführenden, Schwertverfallenen und an Bettlern!"',
        30: 'Joab und sein Bruder Abisai aber hatten Abner ermordet, weil er ihren Bruder Asahel zu Gibeon im Kampf getötet hatte.',
        31: 'David aber sprach zu Joab und allem Volke bei ihm: "Zerreißt eure Kleider, umgürtet euch mit Bußgewändern und klagt vor Abner her!" Und der König David ging hinter der Bahre.',
        32: 'Sie begruben Abner zu Hebron, und der König weinte laut an Abners Grab. Und alles Volk weinte mit.',
        33: 'Der König aber dichtete auf Abner einen Sang und sprach: "Sollt\' Abner enden, so wie Aberwitzige enden?',
        34: 'Die Arme dein, sie waren nicht zu fesseln und deine Füße nicht zu ketten. Du bist gefallen so, wie man vor Meuchelmördern fällt." - Da weinte alles Volk noch mehr.',
        35: 'Dann kam das ganze Volk, David zum Essen zu nötigen, solange es noch Tag war. Aber David schwur: "Gott tue mir dies und das, wenn ich vor Sonnenuntergang Brot oder sonst etwas koste!"',
        36: 'Dies hatte das ganze Volk wahrgenommen, und es gefiel ihm, wie alles, was der König getan, dem Volke gefiel.',
        37: 'Das ganze Volk aber und ganz Israel sahen an jenem Tage klar, daß es nicht vom König ausgegangen war, Abner, den Nersohn, zu töten.',
        38: 'Auch sprach der König zu seinen Dienern: "Wißt ihr nicht, daß heute ein Fürst und Großer in Israel gefallen ist?',
        39: 'Ich aber bin heute nur ein schwacher und unnützer König. Aber diese Männer, die Serujasöhne, sind für mich zu stark. Vergelte der Herr dem, der den Frevel tat, nach seiner Missetat!"',
    },
    4: {
        1: 'Als Sauls Sohn hörte, daß Abner zu Hebron gestorben sei, ward er mutlos; ganz Israel aber war bestürzt.',
        2: 'Nun hatte Sauls Sohn zwei Häuptlinge. Der eine hieß Baana, der andere Rekab, Söhne des Beerotiters Rimmon, aus den Söhnen Benjamins. Denn auch Beerot wird zu Benjamin gerechnet.',
        3: 'Aber die Beerotiter flohen nach Gittim und waren dort zu Gast bis auf diesen Tag.',
        4: 'Sauls Sohn Jonatan nun hatte einen Sohn, der an beiden Füßen lahm war. Er war fünf Jahre alt gewesen, als die Nachricht von Saul und Jonatan aus Jezreel kam. Da packte ihn seine Amme und floh. In der Hast ihrer Flucht aber fiel er hin und ward gelähmt. Er hieß Mephiboset.',
        5: 'Die Söhne des Beerotiters Rimmon nun, Rekab und Baana, zogen aus und betraten während der Mittagshitze Isbosets Haus. Er hielt eben seinen Mittagsschlaf.',
        6: 'So waren sie mitten ins Haus gekommen, als wollten sie Weizen kaufen. Da stachen sie ihn in den Bauch. Dann waren Rekab und sein Bruder Baana entflohen.',
        7: 'Sie waren also in das Haus gekommen. Er aber schlief auf dem Bett in seinem Schlafzimmer. Da schlugen sie ihn und töteten ihn. Dann hieben sie ihm das Haupt ab. Sie nahmen nun seinen Kopf und gingen die ganze Nacht die Steppe entlang.',
        8: 'Dann brachten sie Isbosets Haupt nach Hebron zu David und sprachen zum König: "Da ist das Haupt des Isboset, des Sohnes deines Feindes Saul, der dir nach dem Leben getrachtet. So gab der Herr meinem Herrn heute Rache an Saul und seinen Nachkommen."',
        9: 'Da antwortete David Rekab und seinem Bruder Baana, den Söhnen des Beerotiters Rimmon, und sprach: "So wahr der Herr lebt, der mein Leben aus aller Not befreit hat!',
        10: "Daß ich den, der mir gemeldet 'Saul ist tot' und der sich für einen Glücksboten gehalten, festnahm und in Siklag niederhieb, das ist mein Botenlohn gewesen.",
        11: 'Wenn nun ruchlose Menschen einen rechtschaffenen Mann in seinem Haus auf seinem Lager ermordet haben, muß ich da nicht sein Blut von euch fordern und euch vom Erdboden tilgen?"',
        12: 'Und David gebot den Knechten, und sie schlugen sie nieder, hieben ihnen Hände und Füße ab und hängten sie am Teich zu Hebron auf. Das Haupt des Isboset aber nahmen sie mit; dann begruben sie ihn in Abners Grab zu Hebron.',
    },
    5: {
        1: 'Da kamen alle Stämme Israels zu David nach Hebron und sprachen: "Wir sind auch dein Fleisch und dein Bein.',
        2: 'Schon längst, als noch Saul König über uns war, bist du es gewesen, der Israel aus- und zurückgeführt hat. Auch sprach der Herr zu dir: \'Du sollst mein Volk Israel weiden und Fürst über Israel sein!\'"',
        3: 'Also kamen alle Ältesten Israels zum König nach Hebron. Und der König schloß mit ihnen einen Bund zu Hebron vor dem Herrn. Dann salbten sie David zum König über Israel.',
        4: 'Dreißig Jahre alt war David, als er König wurde, und vierzig Jahre hat er regiert.',
        5: 'In Hebron hat er über Juda sieben Jahre und sechs Monate regiert. In Jerusalem hat er dreiunddreißig Jahre regiert über ganz Israel und Juda.',
        6: 'Der König zog nun mit seinen Mannen nach Jerusalem wider den Jebusiter, der in der Gegend saß. Da sagte man zu David: "Du kommst nur hinein, wenn die Dunklen und die Blonden deine Sklaven sind." Das sollte heißen: \'David kommt nicht hinein.\'',
        7: 'Aber David erstürmte die Burg Sion, das ist die Davidsstadt.',
        8: 'Da sprach David an jenem Tage: "An den Hof kommt jeder, der die Blonden und die Dunklen schlägt, selbst ein Jebusiter." Sie waren David in der Seele zuwider. Deshalb sagte man: "Kein Dunkler und kein Blonder darf das Haus betreten."',
        9: 'Dann setzte sich David in die Burg und nannte sie Davidsstadt. Und David baute ringsum von der Bastei nach innen.',
        10: 'So ward David allmählich immer mächtiger, war doch der Herr, der Gott der Heerscharen, mit ihm.',
        11: 'Und so sandte Chiram, König von Tyrus, Boten an David mit Zedernholz und Zimmerleuten und Steinmetzen. Und sie bauten David ein Haus.',
        12: 'So erkannte David, daß ihn der Herr als König über Israel bestätigt und daß er wegen seines Volkes Israel sein Königtum hochgebracht hatte.',
        13: 'David aber nahm noch mehr Nebenweiber und Weiber von Jerusalem, nachdem er von Hebron gekommen war. Auch wurden David noch Söhne und Töchter geboren.',
        14: 'Dies sind die Namen der ihm zu Jerusalem Geborenen: Sammua, Sobab, Natan und Salomo,',
        15: 'Ibchar, Elisua, Nepheg, Japhia,',
        16: 'Elisama, Eljada und Eliphelet.',
        17: 'Die Philister aber hörten, daß man David zum König über ganz Israel gesalbt habe. Da zogen alle Philister hinauf, David zu suchen. David aber hörte es und zog nach der Bergfeste hinab.',
        18: 'Die Philister kamen nun und ließen sich in der Rephaimebene nieder.',
        19: 'Da befragte David den Herrn: "Soll ich gegen die Philister ziehen? Gibst Du sie in meine Hand?" Da sprach der Herr zu David: "Ja! Ich gebe sicher die Philister in deine Hand."',
        20: 'Da zog David nach Baal Perasim. Und dort schlug sie David. Er sprach: "Der Herr hat mir meine Feinde durchbrochen, wie Wasser durchbricht." Deshalb nennt man jenen Ort Baal Perasim.',
        21: 'Sie ließen aber ihre Götzenbilder dort im Stich, und David mit seinen Leuten nahm sie mit.',
        22: 'Abermals zogen die Philister herauf und ließen sich in der Rephaimebene nieder.',
        23: 'Da befragte David den Herrn. Er sprach: "Du sollst nicht hinaufziehen! Wende dich gegen ihren Rücken und komme über sie von den Geröllhalden her!',
        24: 'Hörst du Geräusch von Schritten auf den oberen Rändern der Geröllhalden, dann brich los! Denn dann zieht der Herr vor dir her, im Philisterlager dreinzuschlagen."',
        25: 'Und David tat, wie ihm der Herr befohlen, und schlug die Philister von Geba bis Gezer.',
    },
    6: {
        1: 'David versammelte nochmals alle Erlesenen in Israel, 30.000.',
        2: 'Dann brach David auf und zog mit dem ganzen Volke bei ihm von Baalat Juda aus, von dort die Gotteslade heraufzuholen, wo der Name des Herrn der Heeresscharen, der auf Cheruben thront, angerufen worden war.',
        3: 'Sie luden nun die Gotteslade auf einen neuen Wagen und brachten sie aus Abinadabs Haus, das zu Gibea stand. Den neuen Wagen aber lenkten Uzza und Achjo, Abinadabs Söhne.',
        4: 'So brachten sie ihn aus Abinadabs Haus zu Gibea samt der Gotteslade fort. Achjo aber schritt vor der Lade.',
        5: 'Und David und das ganze Haus Israel tanzten vor dem Herrn unter dem Klange von Zithern, Harfen, Pauken, Schellen und Zimbeln.',
        6: 'Als sie aber an ein bebautes Feldstück kamen, griff Uzza nach der Gotteslade und hielt sich daran fest, weil ihn die Rinder ins Wanken gebracht hatten.',
        7: 'Da entbrannte des Herrn Zorn über Uzza. Und Gott schlug ihn dort wegen des Vergehens. So starb er dort neben der Gotteslade.',
        8: 'Da ward David mißgestimmt, daß der Herr den Uzza geschlagen hatte. Und er nannte jenen Ort "Schlag des Uzza", wie er jetzt noch heißt.',
        9: 'David aber fürchtete sich vor dem Herrn an jenem Tage und sprach: "Wie soll da die Lade des Herrn zu mir kommen?"',
        10: 'Und David wollte die Lade des Herrn nicht mehr zu sich in die Davidsstadt bringen. So ließ sie David beiseite führen, in das Haus des Gatiters Obededom.',
        11: 'So blieb die Lade des Herrn im Hause des Gatiters Obededom drei Monate. Aber der Herr segnete Obededom und sein ganzes Haus.',
        12: 'Da ward dem König David gemeldet: "Der Herr segnete Obededoms Haus und all seinen Besitz um der Gotteslade willen." Da ging David hin und holte unter Jubel die Gotteslade nach der Davidsstadt.',
        13: 'Sooft nun die Träger der Lade des Herrn sechs Schritte gemacht hatten, opferte er ein Rind und ein Mastkalb.',
        14: 'Und David tanzte mit aller Kraft vor dem Herrn. David aber war mit einem leinenen Ephod umgürtet.',
        15: 'So führten David und das ganze Haus Israel die Lade des Herrn unter Jauchzen und mit lautem Posaunenschall hinauf.',
        16: 'Als aber die Lade des Herrn in die Davidsstadt einzog, hatte sich Sauls Tochter Mikal durch das Fenster gebeugt. Da sah sie den König David vor dem Herrn springen und tanzen. Und sie verachtete ihn in ihrem Herzen.',
        17: 'Sie aber brachten die Lade des Herrn und stellten sie an ihren Platz in dem Zelt, das David für sie aufgeschlagen hatte. Dann brachte David vor dem Herrn Brand- und Mahlopfer dar.',
        18: 'Als David fertig war, Brand- und Mahlopfer darzubringen, begrüßte er das Volk im Namen des Herrn der Heerscharen.',
        19: 'Und er verteilte an alles Volk, für die ganze Menge Israels, Männer und Weiber, je einen Brotkuchen, einen Laib und einen Traubenkuchen. Dann ging ein jeder aus dem Volk in sein Haus.',
        20: 'David kehrte nun heim, sein Haus zu begrüßen. Da trat Sauls Tochter Mikal dem David entgegen und sprach: "Wie ehrenvoll hat sich heute Israels König betragen, der sich heute vor den Augen der Mägde seiner Diener entblößt hat, wie sich die Verrückten entblößen!"',
        21: 'Da sprach David zu Mikal: "Dies geschah zu Ehren des Herrn, der mich vor deinem Vater und seinem ganzen Haus vorgezogen hat, um mich zum Fürsten über das Volk des Herrn, über Israel, zu bestellen. So habe ich vor dem Herrn gespielt.',
        22: 'Und ich erniedrige mich noch mehr als hier und will in deinen Augen klein sein. Bei den Mägden, von denen du gesprochen, bei ihnen möchte ich mir Ehre holen."',
        23: 'Und Sauls Tochter Mikal bekam kein Kind bis zu ihrem Todestag.',
    },
    7: {
        1: 'David wohnte nun in seinem Hause, und der Herr hatte ihm Ruhe ringsum vor all seinen Feinden verschafft.',
        2: 'Da sprach der König zum Propheten Natan: "Sieh doch! Ich wohne in einem Zedernhause. Die Gotteslade aber weilt in einem bloßen Zelt."',
        3: 'Da sprach Natan zum König: "Tu alles, was du im Sinne hast! Denn der Herr ist mit dir."',
        4: 'Aber noch in der gleichen Nacht erging das Wort des Herrn an Natan:',
        5: '"Gehe hin und sage meinem Knechte David: \'So spricht der Herr: Du willst ein Haus mir bauen zu meinem Sitze?',
        6: 'Ich habe nie in einem Haus gewohnt seit jener Zeit, da ich die Söhne Israels aus Ägypterland geführt, bis hin zu diesem Tag. Ich zog in einem Wohnzelt umher.',
        7: 'Habe ich, solange ich bei all den Söhnen Israels umhergezogen, jemals ein Wort zu einem Führer Israels gesagt, den ich beauftragt, Israel, mein Volk, zu weiden: "Warum baut ihr mir nicht ein Zedernhaus?"\'',
        8: "So sage nunmehr zu meinem Knechte David: 'So spricht der Herr der Heerscharen: Ich habe von der Weide, aus der Herde dich hinweggeholt, auf daß du meines Volkes Israel Gebieter seiest.",
        9: 'Ich war mit dir allüberall, wohin du gingst, und tilgte vor dir alle deine Feinde. Ich habe einen großen Namen dir geschaffen, gleich dem der Großen auf der Erde.',
        10: 'Ich habe eine Stätte meinem Volke Israel bestimmt und es dann eingepflanzt, daß es, an seiner Stätte wohnend, nimmer zittere und Ruchlose es nimmer drücken, so wie früher.',
        11: 'Seit jenen Zeiten, da ich Richter meinem Volke Israel bestellt, habe ich dir Ruhe verschafft vor allen deinen Feinden. Der Herr hat dir verkündet, daß dir der Herr ein Haus erbauen werde.',
        12: 'Sind deine Tage voll geworden, und liegst du dann bei deinen Vätern, alsdann bestimme ich auch deinen Leibessprossen zu deinem Nachfolger und ich bestätige sein Königtum.',
        13: 'Er baut ein Haus dann meinem Namen, und ich bestätige seinen Königsthron für alle Zeit.',
        14: 'Ich will ihm Vater sein; er wird mir Sohn. Verfehlt er sich, dann strafe ich ihn mit einer Rute, wie für ganz einfache Menschen, mit Schlägen wie für ganz gewöhnliche Leute.',
        15: 'Und nie weicht meine Huld von dir, wie ich sie Saul entzogen, den ich vor dir beseitigt habe.',
        16: 'Dein Haus mit deinem Königtum wird ewiglich vor mir bestehen. Dein Thron steht fest für alle Zeit.\'"',
        17: 'Genau nach all diesen Worten und diesem ganzen Gesichte hatte Natan zu David gesprochen.',
        18: 'Da kam König David, setzte sich vor den Herrn und sprach: "Wer bin ich, Herr, ach Herr? Was ist mein Haus, daß Du mich bis hierher geführt?',
        19: 'Dies war Dir noch zuwenig, Herr, ach Herr. Du gabst dem Hause Deines Sklaven Verheißungen auf weit hinaus. Und dies ist eine Lehre für die Menschen, Herr, Du Herr.',
        20: 'Was sollte David weiter zu Dir sagen? Du selbst kennst Deinen Knecht, Herr, Herr.',
        21: 'Für Deinen Sklaven, Deinen Hund, hast Du dies Große all getan, um Deinem Sklaven es zu zeigen.',
        22: 'Deswegen bist Du groß, Herr, Gott. Denn Dir ist keiner gleich. Kein Gott ist außer Dir, nach alledem, was wir vernommen.',
        23: 'Wo ist ein Volk, gleich Deinem Israel, ein einzig Volk auf Erden, das sich zum Volke zu erkaufen, ein Gott gegangen wäre, sich einen Namen zu verschaffen, euch Großes zu erweisen und Wunderbares Deinem Land, vor Deinem Volke, das Du Dir aus Ägypten hast erlöst? Wo ist ein Volk und dessen Gott?',
        24: 'Doch Du hast Israel, Dein Volk, für immer Dir zum Volk bestellt und Du bist ihnen, Herr, zum Gott geworden.',
        25: 'Nun aber, Herr und Gott, laß jetzt das Wort für alle Zeiten gültig sein, das Du gesprochen über Deinen Sklaven und sein Haus, und handle so, wie Du gesagt!',
        26: "Dann ist Dein Name groß für alle Zeiten und lautet: 'Herr der Heeresscharen, Gott Israels'. Und Deines Sklaven David Haus steht vor Dir fest.",
        27: "Denn Du, der Heeresscharen Herr, Gott Israels, hast Deinem Sklaven selbst geoffenbart: 'Ich will ein Haus dir bauen.' Drum faßt Dein Sklave sich ein Herz, um dies Gebet Dir vorzutragen.",
        28: 'Nun denn, Herr, Herr! Du selbst bist Gott, und Deine Worte, Herr, sind Wahrheit. Du gabst dies herrliche Versprechen Deinem Sklaven.',
        29: 'Nun laß es Dir gefallen und segne Deines Sklaven Haus, daß es für alle Zeit vor Dir bestehe! Herr, Herr! Du hast es selbst gesagt. So möge auch durch Deinen Segen auf ewig Deines Sklaven Haus gesegnet sein!"',
    },
    8: {
        1: 'Danach schlug David die Philister und demütigte sie. David nahm auch die Talsperre den Philistern aus der Hand.',
        2: 'Dann schlug er Moab und vermaß es mit der Meßschnur, nachdem er sie zu Boden geworfen hatte. Je zwei Schnüre maß er zur Verwüstung ab und je eine Schnur zur Aufpflanzung. So ward Moab David untertan und steuerpflichtig.',
        3: 'Dann schlug David den König von Soba, Hadadezer, Rechobs Sohn, als er auszog, seine Hand nach dem Strom zu strecken.',
        4: 'David nahm ihm 1.700 Wagenkämpfer und 20.000 Mann Fußvolk ab. Alle Rosse lähmte David. Nur 100 Pferdewagen ließ er davon übrig.',
        5: 'Da kamen die damaszenischen Aramäer dem König von Soba, Hadadezer, zu Hilfe. Aber David schlug von den Aramäern 22.000 Mann.',
        6: 'Dann setzte David im damaszenischen Aram Vögte ein. So wurden die Aramäer David untertan und steuerpflichtig. Der Herr half David überall, wohin er zog.',
        7: 'David nahm nun die goldenen Schilde der Knechte Hadadezers und brachte sie nach Jerusalem.',
        8: 'Aus Tebach und aus Berotai, den Städten des Hadadezers, nahm König David sehr viel Erz.',
        9: 'Da hörte Toi, der König von Chamat, David habe die ganze Streitmacht Hadadezers geschlagen.',
        10: 'So sandte nun Toi seinen Sohn Hadoram zum König David, ihn zu begrüßen und zu beglückwünschen wegen seines siegreichen Kampfes mit Hadadezer. Denn Hadadezer war Tois Kriegsgegner. Er brachte silberne, goldene und eherne Gefäße.',
        11: 'Auch sie weihte König David dem Herrn, samt dem Silber und Gold, das er von all den Völkern geweiht, die er unterjocht hatte,',
        12: 'von den Edomitern, Moabitern, Ammonitern, Philistern und Amalekitern und von der Beute des Hadadezer, des Königs von Soba und Sohnes des Rechob.',
        13: 'So machte sich David einen Namen nach seiner Rückkehr vom Siege aber die 18.000 Mann Aramäer im Salztale.',
        14: 'In Edom bestellte er Vögte, hatte er doch mit ganz Edom ein Abkommen getroffen. So ward ganz Edom David untertan. Der Herr half nämlich David überall, wohin er zog.',
        15: 'So regierte David über ganz Israel. Und David übte Recht und Gerechtigkeit an seinem ganzen Volke.',
        16: 'Über das Heer war Serujas Sohn Joab gesetzt, und Achiluds Sohn Josaphat war Kanzler.',
        17: 'Achitubs Sohn Sadok und Achimelek, Ebjatars Sohn, waren Priester, Seraja Schreiber.',
        18: 'Benaja, Jojadas Sohn, war Anführer der Bogenschützen und der Schildträger. Davids Söhne aber waren Landleute.',
    },
    9: {
        1: 'Da fragte David: "Ist noch jemand von Sauls Haus übrig? Ich möchte ihm um Jonatans willen Liebes tun."',
        2: 'Nun war im Hause Sauls ein Diener, namens Siba. Ihn rief man zu David, und der König fragte ihn: "Bist du Siba?" Er sprach: "Ja, dein Sklave."',
        3: 'Da fragte ihn der König: "Ist niemand mehr von Sauls Haus da, daß ich an ihm Gottes Liebe erweise?" Da sprach Siba zum König: "Noch ist ein Sohn Jonatans da, aber mit lahmen Beinen.',
        4: 'Da sprach zu ihm der König: "Wo ist er?" Da sprach Siba zum König: "Er ist im Hause Makirs, des Sohnes Ammiels, zu Lodebar."',
        5: 'Da sandte König David hin und ließ ihn aus dem Hause des Ammielsohnes Makir aus Lodebar holen.',
        6: 'So kam Mephiboset, der Sohn des Saulssohns Jonatan zu David. Er warf sich auf sein Antlitz und huldigte. Da sprach David: "Mephiboset!" Er sprach: "Hier ist dein Sklave."',
        7: 'Da sprach David zu ihm: "Fürchte nichts. Ich will dir Liebes tun wegen deines Vaters Jonatan. Ich gebe dir das ganze Grundstück deines Ahnherrn Saul zurück, und du selbst magst jederzeit an meinem Tische speisen."',
        8: 'Da verneigte er sich und sprach: "Was ist dein Sklave, daß du dich einem toten Hund zuwendest, wie ich einer bin?"',
        9: 'Da rief der König nach Siba, Sauls Diener, und sprach zu ihm: "Alles, was Saul und seinem ganzen Haus gehört hat, gebe ich dem Sohne deines Herrn.',
        10: 'Bestelle ihm das Land, du, deine Söhne und deine Sklaven, und heimse es ihm ein, damit das Haus deines Herrn Speise zur Zehrung habe! Deines Herrn Sohn Mephiboset soll jederzeit an meinem Tische speisen!" Siba selbst aber besaß fünfzehn Söhne und zwanzig Sklaven.',
        11: 'Da sprach Siba zum König: "Ganz so, wie mein Herr, der König, seinem Sklaven befiehlt, wird dein Sklave tun, obschon Mephiboset an meinem Tisch speisen könnte, wie einer der Königssöhne."',
        12: 'Mephiboset aber hatte einen kleinen Sohn, namens Mika. Alle Insassen in Sibas Haus dienten Mephiboset.',
        13: 'Mephiboset nun wohnte zu Jerusalem; denn er speiste ständig an des Königs Tafel, obwohl er an beiden Beinen gelähmt war.',
    },
    10: {
        1: 'Danach starb der Ammoniterkönig, und sein Sohn Chanun ward an seiner Statt König.',
        2: 'Da sprach David: "Ich will dem Chanun, des Nachas Sohn, Liebes tun, wie sein Vater mir Liebes hat getan." So schickte David hin, ihn durch seine Diener wegen seines Vaters zu trösten. So kamen Davids Diener ins Ammoniterland.',
        3: 'Da sprachen die Ammoniterfürsten zu ihrem Herrn Chanun: "Ehrt David nach deiner Ansicht deinen Vater, daß er dir Tröster schickt? Sendet nicht David seine Diener zu dir, die Stadt auszuspähen, auszuforschen und zu erkunden?',
        4: 'Da ergriff Chanun Davids Diener, schor ihnen den Bart halb ab und schnitt ihnen die Kleider halb bis ans Gesäß weg. So schickte er sie fort.',
        5: 'Als man dies David meldete, sandte er ihnen entgegen. Denn die Männer waren schwer beschimpft. Der König ließ ihnen sagen: "Bleibt in Jericho, bis euch der Bart gewachsen ist! Dann kommt heim!"',
        6: 'Die Ammoniter aber merkten, daß sie sich bei David verhaßt gemacht hatten. Da schickten die Ammoniter hin und dingten bei Aram in Bet Rechob und bei Aram in Soba 20.000 Fußtruppen und vom König von Maaka 1.000 Mann und 12.000 Mann von Tob.',
        7: 'Als dies David hörte, sandte er Joab und das ganze Heer, die Krieger, aus.',
        8: 'Da rückten die Ammoniter aus und stellten sich zum Kampfe vor das Stadttor. Die Aramäer von Soba und Rechob aber und die Mannschaften von Tob und Maaka standen für sich im Gelände.',
        9: 'Als Joab sah, daß ihm ein Angriff von vorn und von hinten drohe, wählte er Leute aus allen Erlesenen Israels und stellte sich den Aramäern entgegen.',
        10: 'Den Rest des Volkes aber hatte er seinem Bruder Abisai unterstellt. Auch er stellte sich den Ammonitern entgegen.',
        11: 'Er sprach: "Werden aber die Ammoniter mir zu stark, dann komm du mir zu Hilfe! Werden aber die Aramäer dir zu stark, dann komme ich dir zu helfen.',
        12: 'Sei tapfer! Seien wir mutig für unser Volk und Diener unseres Gottes. Der Herr aber tue, was ihm gefällt!"',
        13: 'So rückten Joab und das Volk bei ihm zum Kampfe gegen die Aramäer vor. Da flohen sie vor ihm.',
        14: 'Als die Ammoniter sahen, daß die Aramäer flohen, flohen auch sie vor Abisai und zogen sich zurück. Da ließ Joab von den Ammonitern ab und kam nach Jerusalem.',
        15: 'Als die Aramäer sahen, daß sie von Israel geschlagen waren, sammelten sie sich.',
        16: 'Und Hadadezer sandte hin und ließ die Aramäer jenseits des Stromes ausrücken. Und sie kamen nach Chelam. Hadadezers Feldherr Sobak aber war an ihrer Spitze.',
        17: 'Dies ward David gemeldet. Da bot er ganz Israel auf, überschritt den Jordan und kam nach Chelam. Da stellten sich die Aramäer David entgegen und kämpften mit ihm.',
        18: 'Aber die Aramäer mußten vor Israel fliehen. Und David schlug von den Aramäern 700 Wagenkämpfer und 40.000 Mann Fußvolk. Auch ihren Feldherrn Sobak schlug er, daß er dort starb.',
        19: 'Als alle Könige, Hadadezers Untergebene, sahen, daß sie von Israel geschlagen waren, schlossen sie mit Israel Frieden und waren ihm untertan. Die Aramäer aber hüteten sich, den Ammonitern weiter zu helfen.',
    },
    11: {
        1: 'Um die Jahreswende, wenn die Könige ins Feld ziehen, sandte David den Joab und seine Diener mit ihm und ganz Israel hin. Sie verheerten das Land der Ammoniter und belagerten Rabba. David aber blieb in Jerusalem.',
        2: 'An einem Abend erhob sich David von seinem Lager und erging sich auf dem Dache des Königshauses. Da sah er vom Dache aus ein badendes Weib. Das Weib aber war sehr schön.',
        3: 'David sandte nun hin und erkundigte sich nach dem Weibe. Da sagte man: "Ist das nicht Eliams Tochter Batseba, das Weib des Chittiters Urias?"',
        4: 'Da sandte David Boten und ließ sie holen. Sie kam zu ihm und er schlief bei ihr. Sie hatte sich nämlich von ihrer Unreinigkeit befreit. Dann kehrte sie heim.',
        5: 'So ward das Weib schwanger. Sie sandte nun hin und meldete David: "Ich bin schwanger."',
        6: 'Da sandte David zu Joab: "Sende mir den Chittiter Urias!" Da sandte Joab den Urias zu David.',
        7: 'Urias kam dann zu ihm und David fragte nach Joabs und des Volkes Befinden und nach dem Kriegsglücke.',
        8: 'Dann sprach David zu Urias: "Geh in dein Haus hinunter und wasche dir die Füße!" Und Urias ging aus des Königs Haus. Da folgte ihm ein königlicher Wächter.',
        9: 'Urias aber schlief im Tore des Königshauses bei all den Dienern seines Herrn. Er ging nicht in sein Haus hinab.',
        10: 'Da meldete man David: "Urias ist nicht in sein Haus hinabgegangen." Da sprach David zu Urias: "Kommst du nicht von der Reise? Warum gehst du nicht in dein Haus hinab?"',
        11: 'Da sprach Urias zu David: "Die Lade und Israel und Juda weilen in Hütten. Mein Herr Joab und meines Herrn Diener lagern auf freiem Felde. Da sollte ich in mein Haus gehen, essen und trinken und bei meinem Weibe liegen? Bei deinem Leben und deiner Seele! So etwas tue ich nicht."',
        12: 'Da sprach David zu Urias: "Bleib auch heute noch hier! Morgen entlasse ich dich." So blieb Urias jenen Tag zu Jerusalem.',
        13: 'Am anderen Tage lud ihn David ein. Er aß und trank vor ihm. Schließlich machte er ihn trunken. Am Abend ging er hinaus, auf seinem Lager bei seines Herrn Diener zu schlafen. Aber in sein Haus ging er nicht hinab.',
        14: 'Nun schrieb David am anderen Morgen einen Brief an Joab und sandte ihn durch Urias ab.',
        15: 'Er schrieb in dem Briefe: "Stellt Urias vorn ins heftigste Kampfgewühl! Dann zieht euch von ihm zurück, daß er erschlagen werde und falle!"',
        16: 'Während Joab die Stadt belagerte, stellte er Urias an den Ort, wo, wie er wußte, tapfere Leute stünden.',
        17: 'Die Leute der Stadt machten nun einen Ausfall und kämpften mit Joab. Da fielen einige vom Volk, von Davids Dienern. Auch der Chittiter Urias fand den Tod.',
        18: 'Da sandte Joab hin und berichtete David den ganzen Verlauf des Kampfes.',
        19: 'Er befahl dem Boten: "Berichtest du dem König den ganzen Hergang des Kampfes bis zum Ende',
        20: "und braust der König auf und fragt dich: 'Warum seid ihr zum Treffen so nahe an die Stadt gerückt? Wußtet ihr nicht, daß sie von der Mauer herabschießen?",
        21: 'Wer hat Jerubosets Sohn Abimelek erschlagen? Hat nicht ein Weib auf ihn einen Mühlstein von der Mauer geworfen, daß er zu Tebes starb? Warum seid ihr so nahe an die Mauer gerückt?\', dann sprich: \'Auch dein Diener Urias, der Chittiter, ist gefallen.\'"',
        22: 'Der Bote ging, kam und meldete David alles, was ihm Joab aufgetragen hatte.',
        23: 'Der Bote sprach zu David: "Die Leute sind uns überlegen gewesen; sie drangen gegen uns ins freie Feld. Wir aber drängten sie bis an das Stadttor.',
        24: 'Da schossen die Schützen auf deine Diener von der Mauer, daß von des Königs Dienern etliche den Tod fanden. Auch dein Knecht, der Chittiter Urias, fand den Tod."',
        25: 'Da sprach David zum Boten: "Sprich so zu Joab: \'Kränke dich nicht darüber! Denn das Schwert frißt bald so, bald so. Führe wacker deinen Kampf gegen die Stadt und zerstöre sie!\' So ermutige ihn!"',
        26: 'Des Urias Weib aber vernahm, daß ihr Mann Urias gefallen sei. Da betrauerte sie ihren Gemahl.',
        27: 'Als aber die Trauer vorüber war, sandte David und ließ sie in sein Haus holen. So ward sie sein Weib und gebar ihm einen Sohn. Aber dem Herrn mißfiel, was David getan.',
    },
    12: {
        1: 'So sandte der Herr den Natan zu David. Er kam zu ihm und sagte ihm: "Zwei Männer waren in einer gewissen Stadt, der eine reich, der andere arm.',
        2: 'Der Reiche besaß Schafe und Rinder in großer Zahl.',
        3: 'Der Arme aber hatte nichts als ein einziges Lämmchen, das er gekauft hatte. Er zog es auf, und es wuchs bei ihm auf mit seinen Kindern zusammen. Von seinem Bissen aß es, aus seinem Becher trank es und schlief an seinem Busen. Es galt ihm wie ein Kind.',
        4: 'Da kam Besuch zu dem reichen Manne. Ihm aber war es leid, eines seiner Schafe und Rinder zu nehmen, um es dem Gast, der zu ihm gekommen, zuzubereiten. So nahm er das Lamm des armen Mannes und bereitete es dem Manne, der zu ihm gekommen war."',
        5: 'Da ward David über den Mann sehr zornig und sprach zu Natan: "So wahr der Herr lebt! Der Mann, der dies getan, ist ein Kind des Todes.',
        6: 'Und das Lamm muß er vierfach erstatten, dafür, daß er dies getan und kein Erbarmen geübt hat."',
        7: 'Da sprach Natan zu David: "Du selbst bist der Mann. So spricht der Herr, Israels Gott: \'Ich habe dich zum König über Israel gesalbt. Ich habe dich aus der Hand des Saul gerettet.',
        8: 'Ich gab dir deines Herrn Haus, die Weiber deines Herrn an deinen Busen. Ich gab dir Israels und Judas Haus. Und wäre das zu wenig, so wollte ich dir noch dies und das geben.',
        9: 'Warum hast du des Herren Wort mißachtet und das getan, was ihm mißfällt? Du hast Urias, den Chittiter, mit dem Schwert erschlagen und hast dir seine Frau zum Weib genommen. Du hast ihn durch der Ammoniter Schwert ermordet.',
        10: "Nun weiche nie das Schwert aus deinem eigenen Hause, zur Strafe dafür, daß du mich mißachtet, daß du das Weib Urias´, des Chittiters, dir zum Weibe nahmst!'",
        11: "So spricht der Herr: 'Ich lasse einen Nebenbuhler dir aus deinem Haus erstehen. Ich nehme weg vor deinen Augen deine Weiber und gebe diese deinem Nebenbuhler, daß er im Angesichte dieser Sonne deinen Weibern beiwohne.",
        12: 'Du hast es heimlich zwar getan. Ich aber tue dies im Angesicht des ganzen Israel und vor der Sonne.\'"',
        13: 'Da sprach David zu Natan: "Ich habe gegen den Herrn gesündigt." Da sprach Natan zu David: "So sieht der Herr dir auch deine Sünde nach. Du wirst nicht sterben.',
        14: 'Weil du aber auf die Feinde des Herrn dabei keine Rücksicht genommen, soll auch der Sohn, der dir geboren ward, sterben."',
        15: 'Und Natan ging nach Hause. Der Herr aber schlug das Kind, das des Urias Witwe dem David geboren hatte. Es ward todkrank.',
        16: 'Da suchte David um des Knaben willen Gott auf. Und David fastete streng, hielt Nachtwache und lag über Nacht auf der Erde.',
        17: 'Da traten die Ältesten seines Hauses zu ihm, ihn vom Boden aufzuheben. Er aber wollte nicht und genoß keine Speise mit ihnen.',
        18: 'Am siebten Tage starb der Knabe. Da fürchteten sich Davids Diener, ihm zu sagen, der Knabe sei tot. Denn sie sagten: "Solange der Knabe lebte, haben wir ihm zugeredet; aber er gab uns kein Gehör. Wie können wir ihm sagen: \'Der Knabe ist tot!\' Er könnte Unheil anrichten."',
        19: 'David aber sah seine Diener miteinander flüstern. Da erkannte David, daß der Knabe tot war. Und David sprach zu seinen Dienern: "Ist der Knabe gestorben?" Sie sagten: "Ja."',
        20: 'Da stand David vom Boden auf, wusch sich und salbte sich und wechselte sein Gewand. Dann ging er in das Haus des Herrn und warf sich nieder. Hierauf ging er in sein eigen Haus und verlangte etwas. Da setzten sie ihm Speise vor, und er aß.',
        21: 'Da sprachen seine Diener zu ihm: "Was für ein Gebaren ist dies, das du zeigst? Als der Knabe noch lebte, hast du gefastet, dazu weintest du. Und nun, da der Knabe tot ist, stehst du auf und genießest Speise?"',
        22: 'Da sprach er: "Solange der Knabe lebte, habe ich gefastet und dazu geweint, weil ich gedacht habe: \'Wer weiß? Der Herr kann sich meiner erbarmen, daß der Knabe leben bleibt.\'',
        23: 'Nun ist er aber tot. Wozu sollte ich fasten? Kann ich ihn wieder zurückbringen? Ich gehe zu ihm. Aber er kommt nicht wieder zu mir."',
        24: 'Und David tröstete sein Weib Batseba. Er ging zu ihr und wohnte ihr bei. Da gebar sie einen Sohn und sie nannte ihn Salomo. Und der Herr hatte ihn lieb.',
        25: 'Und durch den Propheten Natan ließ er ihn Jedidia nennen wegen des Herrn.',
        26: 'Joab aber bestürmte das ammonitische Rabba und eroberte die Königsstadt.',
        27: 'Da sandte Joab Boten zu David und ließ melden: "Ich habe Rabba bestürmt und die Zufluchtsstadt erobert.',
        28: 'Nun sammle den Rest des Volkes! Bestürme die Stadt und erobere sie vollends, damit nicht ich die Stadt erobere und mein Name darüber genannt würde!"',
        29: 'Da sammelte David alles Volk und zog nach Rabba, bestürmte und eroberte es.',
        30: 'Dann nahm er die Krone Milkoms von dessen Kopf. Sie wog ein Talent Gold, dabei war ein Edelstein, und er kam auf Davids Haupt. Die Beute der Stadt führte er in großer Menge heim.',
        31: 'Das Volk darin aber hatte er herausgeführt; dann legte er Feuerbrände an und hieb und stach mit Eisen darein; sie selber aber hatte er der Königsfron überwiesen. So tat er mit allen Ammoniterstädten. Dann kehrten David und das ganze Volk nach Jerusalem zurück.',
    },
    13: {
        1: 'Hernach geschah folgendes: Absalom, Davids Sohn, hatte eine schöne Schwester namens Tamar. In sie verliebte sich der Davidssohn Amnon.',
        2: 'Und Amnon quälte sich ganz krank wegen seiner Schwester Tamar. Denn sie war eine züchtige Jungfrau. Und so erschien es dem Amnon unmöglich, mit ihr etwas zu tun.',
        3: 'Nun hatte Amnon einen Freund namens Jonadab, Sohn des Sima, eines Bruders Davids, Jonadab aber war ein sehr kluger Mann.',
        4: 'Er sprach zu ihm: "Warum bist du, Königssohn, Morgen für Morgen so elend? Willst du es mir nicht sagen?" Da sprach Amnon zu ihm: "Ich liebe Tamar, meines Bruders Absalom Schwester."',
        5: 'Da sprach Jonadab zu ihm: "Lege dich zu Bett und stell dich krank! Und kommt dein Vater, dich zu besuchen, dann sage ihm: \'Käme doch meine Schwester Tamar und brächte mir etwas zu essen! Wenn sie vor meinen Augen das Essen bereitete, daß ich es sehe, dann wollte ich gerne von ihrer Hand essen.\'"',
        6: 'So legte sich Amnon nieder und stellte sich krank. Und der König kam, ihn zu besuchen. Da sprach Amnon zum König: "Käme doch meine Schwester Tamar und machte vor meinen Augen ein paar Kuchen, daß ich von ihrer Hand essen könnte!"',
        7: 'Da sandte David nach Haus zu Tamar und ließ sagen: "Geh doch in deines Bruders Amnon Haus und bereite ihm das Essen."',
        8: 'Da ging Tamar in ihres Bruders Amnon Haus. Er aber lag zu Bette. Sie nahm den Teig, knetete ihn und bereitete vor seinen Augen die Kuchen und buk sie.',
        9: 'Dann nahm sie die Pfanne und stürzte sie vor ihn. Er aber weigerte sich zu essen. Dann sprach Amnon: "Entfernt alle von hier!" Da ging alles von ihm hinaus.',
        10: 'Dann sprach Amnon zu Tamar: "Bring das Essen in das innere Gemach! Dann will ich von deiner Hand essen." Da nahm Tamar die Kuchen, die sie gemacht hatte, und brachte sie ihrem Bruder Amnon ins innere Gemach.',
        11: 'Sie bot ihm zu essen. Da faßte er sie und sprach zu ihr: "Komm, leg dich zu mir, meine Schwester!"',
        12: 'Da sprach sie zu ihm: "Nicht doch, mein Bruder, entehre mich nicht! Denn so etwas tut man nicht in Israel. Tu nicht solche Freveltat!',
        13: 'Wohin sollte ich meine Schande tragen? Du selbst gältest in Israel als einer der größten Missetäter. Sprich doch lieber mit dem König! Er versagt mich dir nicht."',
        14: 'Er aber wollte ihr kein Gehör schenken, sondern überwältigte und vergewaltigte sie. Und so wohnte er ihr bei.',
        15: 'Dann aber faßte Amnon eine überaus tiefe Abneigung gegen sie. Ja, die Abneigung, die er gegen sie faßte, war größer als die Liebe, die er zu ihr gehabt hatte. Und so sprach Amnon zu ihr: "Auf! Fort!"',
        16: 'Sie sprach zu ihm: "Nein! Dieses große Unrecht, wenn du mich fortjagtest, wäre noch größer als das andere, das du mir angetan!" Er aber wollte nicht auf sie hören.',
        17: 'Er rief seinen Burschen und Diener und sprach: "Schaff mir die da fort auf die Straße. Verriegle die Tür hinter ihr!"',
        18: 'Sie aber trug einen buntgewirkten Leibrock. Denn solche Obergewänder hatten von alters her die Königstöchter, solange sie Jungfrauen waren. Sein Diener führte sie nun auf die Straße und verriegelte hinter ihr die Tür.',
        19: 'Da streute sich Tamar Asche auf das Haupt, zerriß den buntgewirkten Leibrock, den sie trug, schlug die Hände über dem Kopf zusammen und ging unter beständigem Wehgeschrei davon.',
        20: 'Da sprach ihr Bruder Absalom zu ihr: "War dein Bruder Amnon bei dir? Nun, meine Schwester, schweig still! Dein Bruder ist es. Nimm dir diese Sache nicht zu Herzen!" So blieb Tamar, und zwar unvermählt, im Hause ihres Bruders Absalom.',
        21: 'Der König aber erfuhr den ganzen Vorgang. Da ward er sehr zornig.',
        22: 'Absalom aber redete kein Wort mit Amnon, weder im Bösen noch im Guten. Aber Absalom haßte den Amnon, weil er seine Schwester Tamar entehrt hatte.',
        23: 'Nach zwei Jahren hielt Absalom Schafschur in Baal Chasor bei Ephraim. Dazu lud Absalom alle Königssöhne ein.',
        24: 'Absalom kam nämlich zum König und sprach: "Dein Sklave hält heute Schafschur. Möchten doch der König und seine Diener mit deinem Sklaven gehen!"',
        25: 'Da sprach der König zu Absalom: "Nicht doch, mein Sohn! Wir wollen nicht alle hingehen, daß wir dir nicht beschwerlich fallen." Da drängte er ihn. Er aber wollte nicht gehen, sondern segnete ihn.',
        26: 'Da sprach Absalom: "Wenn nicht, dann gehe wenigstens mein Bruder Amnon mit uns!" Da fragte ihn der König: "Wozu soll er mit dir gehen?"',
        27: 'Absalom aber drang in ihn. Und so sandte er Amnon und alle anderen Königssöhne mit ihm.',
        28: 'Absalom aber befahl seinen Dienern: "Wenn Amnon vom Wein guter Laune sein wird, und ich spreche zu euch: \'Haut Amnon nieder!\' Dann tötet ihn! Fürchtet nichts! Gebe nicht ich euch den Befehl? Seid also mutig und zeigt euch als wackere Mannen!"',
        29: 'Absaloms Diener taten an Amnon, wie Absalom geboten hatte. Da sprangen alle anderen Königssöhne auf, jeder schwang sich auf sein Maultier und floh.',
        30: 'Noch waren sie unterwegs. Da war schon das Gerücht zu David gedrungen, Absalom habe alle Königssöhne erschlagen; nicht einer von ihnen sei mehr übrig.',
        31: 'Da stand der König auf, zerriß seine Gewänder und warf sich zur Erde, und alle seine Diener standen mit zerrissenen Kleidern da.',
        32: 'Da hob Jonadab an, der Sohn des Davidsbruders Sima, und sprach: "Mein Herr sage nicht, man habe all die jungen Königssöhne umgebracht! Amnon allein ist tot. Denn so wie Absalom ist, war es geplant seit dem Tage, da jener seine Schwester Tamar entehrt hatte.',
        33: 'So setze sich mein Herr und König nicht den Gedanken in den Kopf, alle Königskinder seien tot! Amnon allein ist tot.',
        34: 'Absalom aber floh." Der wachhabende Diener hielt eben Ausschau. Da sah er eine Menge Leute auf der Straße hinter ihm von der Bergseite kommen.',
        35: 'Da sprach Jonadab zum König: "Die Königssöhne kommen. Wie dein Sklave sagte, so war es."',
        36: 'Er hatte eben ausgeredet. Da waren die Königssöhne angekommen; sie erhoben ihre Stimme und weinten. Auch der König und all seine Diener hatten überlaut geweint.',
        37: 'Absalom aber war geflohen; er ging zu Talmai, dem König von Gesur und Ammichuds Sohn. Jener aber trauerte um seinen Sohn die ganze Zeit.',
        38: 'Absalom aber war entflohen; er ging nach Gesur. Dort blieb er drei Jahre.',
        39: 'David aber dachte schon daran, Absalom entgegenzukommen. Denn er hatte sich darüber getröstet, daß Amnon tot war.',
    },
    14: {
        1: 'Joab, Serujas Sohn, merkte nun, daß sich des Königs Herz Absalom zuneigte!',
        2: 'Da schickte Joab nach Tekoa und ließ von dort ein kluges Weib holen. Er sprach zu ihr: "Stell dich trauernd und zieh Trauerkleider an! Salbe dich nicht mit Öl, sondern sei wie ein Weib, das geraume Zeit um einen Toten trauert!',
        3: 'Geh zum König und sprich zu ihm dies!" Nun legte ihr Joab die Worte in den Mund.',
        4: 'Das Weib von Tekoa kam zum König, warf sich auf ihr Antlitz, huldigte und sprach: "Hilf, König!"',
        5: 'Da sprach der König zu ihr: "Was ist dir?" Sie sprach: "Leider bin ich eine Witwe, starb doch mein Mann.',
        6: 'Deine Sklavin hatte zwei Söhne. Aber sie stritten miteinander auf dem Felde, und niemand schlichtete zwischen ihnen. So schlug der eine den anderen und tötete ihn.',
        7: 'Nun erhebt sich die ganze Sippe gegen deine Sklavin und ruft: \'Gib den Brudermörder heraus, daß wir ihn töten für das Leben seines Bruders, den er erschlagen hat. Wir wollen so zugleich den Erben beseitigen.\' So wollen sie meine letzte Kohle löschen und meinem Manne nicht Namen noch Nachkommen auf Erden lassen."',
        8: 'Da sprach der König zum Weibe: "Geh heim! Ich werde deinetwegen verfügen."',
        9: 'Da sprach das Weib von Tekoa zum König: "Mich, Herr und König, träfe das Unrecht, und meine Familie. Der König und sein Thron aber bleiben unangetastet."',
        10: 'Da sprach der König: "Wenn jemand so zu dir spricht, dann melde mir ihn! Er soll dich nicht mehr antasten!"',
        11: 'Sie sprach: "Möchte doch der König an den Herrn, seinen Gott, denken - sonst könnte der Bluträcher zuviel verderben -, daß sie nicht meinen Sohn umbringen!" Da sprach er: "So wahr der Herr lebt! Nicht ein Haar deines Sohnes soll zu Boden fallen!"',
        12: 'Da sprach das Weib: "Dürfte doch deine Sklavin an meinen Herrn und König ein Wort richten!" Er sprach: "Sprich!"',
        13: 'Da sprach das Weib: "Warum sinnst du Ähnliches gegen Gottes Volk? Aus dieser Rede des Königs geht hervor, daß es an Sünde grenzt, wenn der König seinen Verbannten nicht zurückruft.',
        14: 'Sterben wir, so werden wir wie Wasser, das, auf den Boden geschüttet, nicht mehr gesammelt werden kann. Aber Gott nimmt nicht das Leben weg, sondern faßt Pläne, damit ein Verbannter nicht zu unserem Schaden verbannt bleibe.',
        15: "Daß ich jetzt gekommen bin, dies dem König, meinem Herrn, zu sagen, das kommt davon, daß mir das Volk Angst gemacht hat. Deine Sklavin aber sagte: 'Ich will doch mit dem König reden. Vielleicht tut der König, was seine Magd sagt.'",
        16: 'Weil der König die Bitte gewährt, seine Magd aus der Hand des Mannes zu retten, der mich und meinen Sohn zugleich aus Gottes Erbe zu tilgen sucht,',
        17: 'So dachte deine Sklavin: \'Möchte doch das Wort meines Herrn und Königs zur Beruhigung dienen!\' Denn wie ein Gottesengel ist mein Herr und König, wenn er Gutes und Böses anhört. Der Herr, dein Gott, sei mit dir!"',
        18: 'Da hob der König an und sprach zu dem Weibe: "Verhehle mir nichts von dem, was ich dich frage!" Da sprach das Weib: "Es spreche doch mein Herr und König!"',
        19: 'Da sprach der König:"Hat Joab dir bei alldem geholfen?" Da hob das Weib an und sprach: "So wahr du lebst, mein Herr und König! Unmöglich ist es, rechts oder links vorbeizukommen an irgend etwas, was mein Herr und König spricht. Ja, dein Diener Joab selbst hat mir den Auftrag gegeben. Er hat deiner Sklavin alle jene Worte in den Mund gelegt.',
        20: 'Um der Sache ein anderes Gesicht zu geben, hat dein Diener Joab dies getan. Aber mein Herr ist weise wie ein Gottesengel; er weiß alles, was im Lande vorgeht."',
        21: 'Da sprach der König zu Joab: "Das hast du getan. So geh und hole den Jüngling Absalom!"',
        22: 'Da warf sich Joab auf sein Antlitz zur Erde, huldigte und segnete den König. Dann sprach Joab: "Heute erfährt dein Sklave, daß ich Huld gefunden in deinen Augen, mein Herr und König, weil der König das Wort seines Sklaven erfüllt."',
        23: 'Dann stand Joab auf, ging nach Gesur und brachte Absalom nach Jerusalem.',
        24: 'Der König aber sprach: "Er gehe in sein Haus! Mein Antlitz darf er nicht sehen!" So ging Absalom in sein Haus. Aber des Königs Antlitz sah er nicht.',
        25: 'So schön aber wie Absalom war in ganz Israel kein Mann, so daß man ihn sehr rühmte. Von der Fußsohle bis zum Scheitel war kein Makel an ihm.',
        26: 'Und wenn er sein Haupt schor, und er schor es von Zeit zu Zeit - weil es ihm beschwerlich ward, schor er es -, so wog das ganze Haar seines Hauptes zweihundert Ringe nach königlichem Gewicht.',
        27: 'Absalom aber wurden drei Söhne und eine Tochter, namens Tamar, geboren. Diese ward ein schönes Weib.',
        28: 'Da saß Absalom zu Jerusalem zwei Jahre. Des Königs Antlitz aber hatte er nicht gesehen.',
        29: 'Da sandte Absalom zu Joab, ihn zum König zu schicken; er aber wollte nicht kommen. So schickte er noch ein zweitesmal. Aber er wollte nicht kommen.',
        30: 'Da sprach er zu seinen Dienern: "Seht! Joab hat ein Feld neben meinem Grundstück und hat Gerste darauf. Geht und steckt es in Brand!" Und Absaloms Diener steckten das Feld in Brand.',
        31: 'Da machte sich Joab auf, ging zu Absalom ins Haus und sprach zu ihm: "Weshalb haben deine Diener mein Feld in Brand gesteckt?"',
        32: 'Da sprach Absalom zu Joab: "Ich habe zu dir gesandt und sagen lassen: \'Komm her!\' Ich möchte dich zum König senden und sagen lassen: \'Wozu bin ich von Gesur heimgekommen? Mir wäre wohler, wäre ich noch dort.\' Nun aber möchte ich des Königs Antlitz sehen. Liegt eine Schuld auf mir, so töte er mich!"',
        33: 'So kam Joab zum König und meldete es ihm. Und er ließ Absalom rufen. So kam er zum König. Da warf er sich auf sein Antlitz zur Erde vor dem König nieder, und der König küßte Absalom.',
    },
    15: {
        1: 'Hernach schaffte sich Absalom Wagen und Pferde an, dazu fünfzig Mann, die vor ihm herliefen.',
        2: 'Absalom aber pflegte sich frühmorgens neben den Torweg zu stellen. Und alle Leute, die eine Streitsache vor den König zur Entscheidung bringen wollten, rief Absalom an und fragte: "Aus welcher Stadt bist du?" Und sagte er: "Dein Knecht ist von dem und dem Stamme Israels",',
        3: 'dann sagte Absalom zu ihm: "Deine Sache ist gut und recht. Aber beim König hört dich niemand an."',
        4: 'Dann sprach Absalom: "Wer bestellte mich zum Richter im Lande? Zu mir dürfte jeder kommen, der einen Streit und Rechtshandel hat. Ich würde ihn nach Recht entscheiden."',
        5: 'Und trat jemand heran, ihm zu huldigen, so streckte er seine Hand aus, hielt ihn fest und küßte ihn.',
        6: 'Also tat Absalom jedem Israeliten, der den König um Entscheidung anging. So bestrickte Absalom das Herz der Männer Israels.',
        7: 'Nach einem halben Jahre sprach Absalom zum König: "Ich möchte verreisen und in Hebron mein Gelübde einlösen, das ich dem Herrn gelobt.',
        8: 'Denn dein Sklave hat ein Gelübde gemacht, als ich zu Gesur in Aram weilte: \'Führt mich der Herr wirklich nach Jerusalem zurück, dann will ich dem Herrn zu Ehren ein Fest feiern.\'"',
        9: 'Da sprach zu ihm der König: "Ziehe hin in Frieden!" Da machte er sich auf und ging nach Hebron.',
        10: 'Absalom aber sandte geheime Boten an alle Stämme Israels und ließ sagen: "Hört ihr Hörnerschall, dann sagt: \'Absalom ist in Hebron König geworden.\'"',
        11: 'Mit Absalom waren aus Jerusalem 200 Männer gezogen; sie waren eingeladen und zogen arglos mit. Sie wußten nämlich nicht das geringste.',
        12: 'Absalom rief auch den Giloniter Achitophel, Davids Ratgeber, aus seiner Stadt Gilo, als er die Opfer darbrachte. So gewann die Verschwörung Kraft, und das Volk ging hin und ward immer zahlreicher bei Absalom.',
        13: 'Da kam der Bote zu David mit der Meldung: "Das Herz der Männer Israels hat sich Absalom zugewandt."',
        14: 'Da sprach David zu all seinen Dienern, die bei ihm zu Jerusalem waren: "Auf zur Flucht! Denn für uns gibt es keine Rettung vor Absalom. Schleunigst fort! Sonst kommt er rasch uns nach und bringt über uns das Schlimmste und schlägt die Stadt mit des Schwertes Schärfe."',
        15: 'Da sprachen des Königs Diener zum König: "Wie der Herr und König wünscht! Wir sind deine Sklaven."',
        16: 'So zog der König aus und sein ganzes Haus mit ihm. Der König aber ließ zehn Frauen zurück, das Haus zu hüten.',
        17: 'So zog der König fort und alles Kriegsvolk mit ihm. Beim letzten Haus machten sie halt.',
        18: 'Und alle seine Diener zogen an ihm vorüber. Ebenso zogen vor dem König alle Bogenschützen und Schildträger vorüber und alle Gatiter, 600 Mann, die ihm aus Gat gefolgt waren.',
        19: 'Da sprach der König zum Gatiter Ittai: "Weshalb gehst auch du mit uns? Kehr um und bleib beim König! Du bist ja ein Ausländer und selbst aus deiner Heimat verbannt.',
        20: 'Gestern kamst du, und heute schon soll ich dich mit uns auf die Irrfahrt nehmen? Ich gehe doch, wohin ich eben gehe. Kehr um und führe deine Brüder mit dir zurück in Liebe und Treue!"',
        21: 'Da hob Ittai an und sprach zum König: "So wahr der Herr lebt, und so wahr mein Herr und König lebt! An dem Orte, wo mein Herr und König sein wird, ob zum Tode, ob zum Leben, dort ist auch dein Sklave."',
        22: 'Da sprach David zu Ittai: "Auf! Zieh vorüber!" Da zog der Gatiter Ittai mit all seinen Leuten und dem ganzen Troß bei ihm vorüber.',
        23: 'Die ganze Umgebung aber weinte laut auf, als alles Kriegsvolk vorüberzog. Der König zog nun in das Kidrontal, und alles Kriegsvolk zog auf den Weg zur Steppe.',
        24: 'Bei ihm waren auch Sadok und alle Leviten, die des Gottesbundes Lade trugen. Sie stellten die Gotteslade hin, und Ebjatar blieb stehen, bis alles Volk aus der Stadt vorübergezogen war.',
        25: 'Da sprach der König zu Sadok: "Bringe die Gotteslade wieder in die Stadt! Finde ich in des Herrn Augen Gnade, dann führt er mich zurück und läßt mich seine Wohnstatt schauen.',
        26: 'Spräche er aber so: \'Ich habe an dir kein Gefallen\', nun, dann bin ich bereit. Er tue mir, wie ihm gefällt!"',
        27: 'Dann sprach der König zum Priester Sadok: "Du sollst der Beobachter sein! Kehre ruhig in die Stadt zurück! Dein Sohn Achimaas und Jonatan, Ebjatars Sohn, eure beiden Söhne seien bei euch!',
        28: 'Seht! Ich warte an den Furten zur Steppe, bis ein Wort von euch kommt, mir Nachricht zu geben."',
        29: 'Da brachten Sadok und Ebjatar die Gotteslade wieder nach Jerusalem, und sie blieben dort.',
        30: 'David aber stieg den Ölberg hinan, im Gehen weinend und das Haupt verhüllt, und er ging barfuß. Auch von allem Kriegsvolk bei ihm verhüllte jeder das Haupt und stieg weinend hinan.',
        31: 'Da meldete man David: "Achitophel ist unter den Verschwörern bei Absalom." Da sprach David: "Herr, betöre Achitophels Rat!"',
        32: 'David kam nun auf die Spitze, wo er zu Gott betete. Da trat ihm der Arkiter Chusai entgegen, mit zerrissenem Rock und Staub auf dem Haupt.',
        33: 'Da sprach David zu ihm: "Gehst du mit mir weiter, dann bist du mir zur Last.',
        34: "Gehst du aber in die Stadt zurück und sagst du zu Absalom: 'Dein Sklave will ich sein, König. Ehedem war ich deines Vaters Sklave. Nun aber bin ich dein Sklave', dann kannst du mir Achitophels Rat zunichte machen.",
        35: 'Sind nicht dort bei dir die Priester Sadok und Ebjatar? Was du aus des Königs Hause hörst, melde den Priestern Sadok und Ebjatar!',
        36: 'Bei ihnen sind ihre beiden Söhne, Achimaas, Sadoks Sohn und Ebjatars Sohn Jonatan. Schickt durch sie an mich alles, was ihr hört!"',
        37: 'So kam Davids Freund Chusai in die Stadt, als Absalom einzog.',
    },
    16: {
        1: 'David hatte den Gipfel nur wenig überschritten. Da kam Mephibosets Diener Siba ihm entgegen mit einem Paar gesattelter Esel. Sie trugen zweihundert Brote, hundert Dörrtrauben, hundert Obstkuchen und einen Schlauch Wein.',
        2: 'Da sprach der König zu Siba: "Was willst du damit?" Siba sprach: "Die Esel sind für das Königshaus zum Reiten, das Brot und das Obst für die Diener zum Essen und der Wein zum Trinken für die in der Wüste Erschöpften."',
        3: 'Da sprach der König: "Wo bleibt aber deines Herrn Sohn?" Siba sprach zum König: "Er bleibt in Jerusalem. Denn er hat gesagt: \'Heute gibt mir Israels Haus das Königtum meines Vaters zurück.\'"',
        4: 'Da sprach der König zu Siba: "Dein ist, was Mephiboset gehört." Siba sprach: "Ich werfe mich nieder. Möchte ich weiter Gnade finden in deinen Augen, mein Herr, König."',
        5: 'Der König David war nun bis Bachurim gekommen. Da trat ein Mann von der Sippe des Saulhauses hervor, Simei, Geras Sohn. Er kam fluchend.',
        6: 'Und warf mit Steinen nach David, nach allen Dienern des Königs David, obwohl alles Kriegsvolk und alle Krieger zu seiner Rechten und Linken waren.',
        7: 'Und also schrie Simei fluchend: "Fort! Fort, Blutmensch, Ruchloser!',
        8: 'Der Herr bringt über dich all das Blut des Hauses Sauls, für den du König geworden bist. Der Herr gab das Königtum deinem Sohne Absalom. Nun bist du in deinem Unglück. Denn du bist ein Blutmensch."',
        9: 'Da sprach Abisai, Serujas Sohn, zum König: "Warum soll dieser tote Hund meinem Herrn und König fluchen? Ich will hinüber und ihm den Kopf abschlagen."',
        10: 'Da sprach der König: "Was habe ich mit euch, ihr Serujasöhne, zu schaffen? Flucht er, so geschieht es, weil der Herr zu ihm gesprochen: \'Fluche David!\' Wer darf da sagen: \'Warum tust du so?\'"',
        11: 'Dann sprach David zu Abisai und all seinen Dienern: "Mein eigener, leiblicher Sohn stellt mir nach dem Leben. Um wieviel leichter dieser Benjaminite? Laßt ihn! Mag er fluchen. Denn der Herr heißt es ihn.',
        12: 'Vielleicht sieht der Herr mein Elend. Dann gibt mir der Herr wieder Glück an Stelle der Verfluchung von heute."',
        13: 'So zog David mit seinen Leuten des Wegs. Simei aber ging an der Bergseite neben ihm und fluchte im Gehen, warf Steine nach ihm und wirbelte Staub auf.',
        14: 'Der König und das ganze Volk bei ihm kamen zur Furt. Und dort erholte er sich.',
        15: 'Absalom aber und das ganze Kriegsvolk, Israels Mannen, waren nach Jerusalem gekommen. Auch Achitophel war bei ihm.',
        16: 'Da kam der Arkiter Chusai, Davids Freund, zu Absalom. Und Chusai sprach zu Absalom: "Es lebe der König! Es lebe der König!"',
        17: 'Da sprach Absalom zu Chusai: "Ist das deine Liebe zu deinem Freunde? Warum bist du nicht mit deinem Freunde gegangen?"',
        18: 'Da sprach Chusai zu Absalom: "Nein! Nur für den bin ich und bei dem bleibe ich, den der Herr erwählt und dies Volk und alle Mannen Israels.',
        19: 'Zweitens: Wem sollte ich dienen? Nicht seinem Sohne? Wie ich deinem Vater gedient, so diene ich auch dir."',
        20: 'Da sprach Absalom zu Achitophel: "Gebt mir euren Rat, was wir tun sollen!"',
        21: 'Da sprach Achitophel zu Absalom: "Geh zu deines Vaters Nebenweibern, die er dagelassen, das Haus zu bewachen! Dann hört ganz Israel, daß du dich bei deinem Vater in Verruf gebracht hast, und alle deine Anhänger werden ermutigt."',
        22: 'So schlug man für Absalom auf dem Dache das Zelt auf. Und Absalom ging zu seines Vaters Nebenweibern vor ganz Israel.',
        23: 'Achitophels Rat aber, den er gab, galt damals, wie wenn jemand Gottes Wort befragt hätte. So galt jeder Rat Achitophels, wie bei David, so bei Absalom.',
    },
    17: {
        1: 'Da sprach Achitophel zu Absalom. "Ich möchte 1',
        2: '000 Mann ausheben, mich aufmachen und noch in der Nacht David nachsetzen. 2 Ich möchte ihn überfallen, solange er matt und mutlos ist. So würde ich ihn erschrecken, und alles Volk bei ihm würde fliehen. So könnte ich den König allein schlagen.',
        3: 'Dann brächte ich alles Volk zu dir zurück; und wenn all die Männer, nach denen du Verlangen trägst, zurückkehren, dann ist das ganze Volk befriedigt."',
        4: 'Und die Rede gefiel Absalom und allen Ältesten Israels.',
        5: 'Da sprach Absalom: "Ruf mir auch den Arkiter Chusai, daß wir hören, was auch er zu sagen hat!"',
        6: 'So kam Chusai zu Absalom. Da sprach Absalom zu ihm: "Solches hat Achitophel gesprochen. Sollen wir sein Wort ausführen? Wenn nicht, so rede du!"',
        7: 'Da sprach Chusai zu Absalom: "Diesmal ist der Rat, den Achitophel gibt, nicht gut."',
        8: 'Und Chusai sagte: "Du kennst deinen Vater und seine Leute, daß sie Helden sind und grimmen Mutes, wie eine der Jungen beraubte Bärin auf dem Feld. Dazu ist dein Vater ein Kriegsmann, der mit dem Kriegsvolk keine Nachtruhe hält.',
        9: "Gewiß ist er jetzt in irgendeiner Schlucht oder an irgendeiner Stelle versteckt. Fallen nun anfangs einige von euch, und hört man es, dann sagt man: 'Eine Niederlage ist unter dem Volk entstanden, das Absalom anhängt.'",
        10: 'Dann zagt selbst der Tapfere, der sonst ein Löwenherz ist. Denn ganz Israel weiß, daß dein Vater ein Held ist und seine Begleiter tapfere Mannen sind.',
        11: 'So rate ich dir: Erst sammle sich ganz Israel von Dan bis Beerseba um dich, wie der Sand am Meer an Menge! Dann zieh du selber in den Kampf!',
        12: 'Stoßen wir dann auf ihn an einem Platze, wo er sich treffen läßt, dann stürzen wir uns auf ihn, wie der Tau auf den Boden fällt. Von ihm und allen Männern bei ihm bleibt auch nicht einer übrig.',
        13: 'Zöge er sich in eine Stadt zurück, so schleppte ganz Israel zu jener Stadt Stricke, und wir schleiften sie ins Tal, bis auch nicht ein Steinchen mehr sich dort fände."',
        14: 'Da sprachen Absalom und alle Männer Israels: "Des Arkiters Chusai Rat ist besser als der des Achitophel." Der Herr aber hatte es angeordnet, daß Achitophels guter Rat zunichte würde, damit der Herr über Absalom das Unheil bringen konnte.',
        15: 'Chusai aber sprach zu den Priestern Sadok und Ebjatar: "So und so hat Achitophel dem Absalom geraten und den Ältesten Israels. Das und das aber habe ich geraten.',
        16: 'Nun schickt eilends hin und meldet David: \'Übernachte nicht bei den Furten zur Steppe! Mögest du übersetzen, damit nicht dem König und dem ganzen Volk bei ihm Verderben werde!\'"',
        17: 'Jonatan aber und Achimaas hielten sich am Walkerbrunnen auf. Eine Magd aber war hingegangen und hatte es ihnen gemeldet. Da gingen sie und meldeten es dem König David; denn sie durften sich nicht in der Stadt sehen lassen.',
        18: 'Ein Knabe aber sah sie und meldete es Absalom. Die beiden aber liefen eilig weiter und kamen in Bachurim zum Hause eines Mannes; der hatte in seinem Hof einen Brunnen. Da stiegen sie hinab.',
        19: 'Das Weib aber nahm eine Decke, breitete sie über den Brunnen und streute Schrotkorn darüber, daß man nichts merkte.',
        20: 'Da kamen Absaloms Diener zu dem Weib ins Haus und fragten: "Wo sind Achimaas und Jonatan?" Da sprach das Weib zu ihnen: "Sie sind zum Wasserbächlein gegangen." Da suchten sie, fanden aber nichts. So kehrten sie nach Jerusalem zurück.',
        21: 'Nach ihrem Weggang stiegen sie aus dem Brunnen und gingen weiter. Dann berichteten sie dem König David. Sie sprachen zu David: "Auf! Setzt eilends über das Gewässer! Denn so und so hat Achitophel gegen euch geraten."',
        22: 'Da machte sich David auf und alles Volk bei ihm, und sie überschritten den Jordan. Bis der Morgen tagte, fehlte nicht ein einziger, der nicht den Jordan überschritten hätte.',
        23: 'Als Achitophel sah, daß sein Rat nicht befolgt wurde, sattelte er den Esel, machte sich auf und ging nach Hause in seine Stadt. Er bestellte sein Haus und erhängte sich. So starb er und ward in seinem väterlichen Grabe bestattet.',
        24: 'David aber war nach Machanaim gekommen. Da überschritt Absalom den Jordan, er und alle Mannen Israels mit ihm.',
        25: 'Absalom aber hatte Amasa an Joabs Stelle über das Heer gesetzt. Amasa war der Sohn eines Israeliten namens Itra, der des Nachas Tochter Abigal, Serujas Schwester und Joabs Mutter, geheiratet hatte.',
        26: 'Israel aber und Absalom lagerten im Lande Gilead.',
        27: 'Als David nach Machanaim kam, brachten Sobi, des Nachas Sohn, aus dem ammonitischen Rabbat, Ammiels Sohn Makir aus Lodebar und der Gileadite Barzillai aus Rogelim',
        28: 'Bündel, Schalen, Töpfergeschirr, Weizen, Gerste, Mehl, geröstetes Korn, Bohnen, Linsen und Röstkorn,',
        29: 'Honig, Sahne, Schafe und Kuhkäse. Sie reichten es David und dem Volke bei ihm zum Essen. Denn sie hatten gesagt: "Das Volk ist in der Steppe hungrig, matt und durstig."',
    },
    18: {
        1: 'David musterte nun das Volk bei ihm und stellte an seine Spitze Anführer über Tausend und über Hundert.',
        2: 'Dann stellte David das eine Drittel des Volkes unter Joabs Befehl, ein Drittel unter den Befehl des Serujasohnes Abisai, des Bruders Joabs, und ein Drittel unter den Gatiter Ittai. Und David sprach zum Volke: "Auch ich rücke mit euch aus."',
        3: 'Da sprach das Volk: "Du darfst nicht ausrücken. Denn, fliehen wir, so grämt man sich nicht um uns. Fiele von uns auch die Hälfte, so grämte man sich nicht um uns. Du aber bist soviel wie von uns zehn Tausendschaften. Auch ist es besser, wenn du uns von der Stadt Hilfe bringen kannst."',
        4: 'Da sprach der König zu ihnen: "Ich tue, was euch gut dünkt." Dann stellte sich der König neben das Tor, und das ganze Volk rückte aus, nach Hunderten und Tausenden.',
        5: 'Da gebot der König Joab, Abisai und Ittai: "Seid mir milde mit Absalom, dem jungen Manne!" Alles Volk hörte, was der König allen Heerführern Absaloms halber gebot.',
        6: 'So zog das Volk gegen Israel ins Feld, und die Schlacht war im Walde von Ephraim.',
        7: 'Da ward dort das Volk Israel von Davids Dienern geschlagen, und dort kam es zu einer schweren Niederlage von 20.000 Mann an jenem Tage.',
        8: 'Der Kampf aber dehnte sich dort über die ganze Gegend, und der Wald fraß mehr Volk, als das Schwert an jenem Tage gefressen hatte.',
        9: 'Absalom aber ward von Davids Dienern angetroffen. Absalom ritt nämlich ein Maultier, und das Maultier kam unter das Geäst einer großen Eiche. Da blieb sein Kopf an der Eiche hängen. Und so schwebte er zwischen Himmel und Erde. Das Maultier aber ging unter ihm durch.',
        10: 'Das sah ein Mann und meldete es Joab und sprach: "Ich habe Absalom an einer Eiche hängen sehen."',
        11: 'Da sprach Joab zu dem Mann, der ihm dies meldete: "Du hast es gesehen? Warum hast du ihn dort nicht niedergeschlagen? An mir wäre es dann, dir zehn Silberlinge und einen Gurt zu geben."',
        12: 'Da sprach der Mann zu Joab: "Und wenn ich ein volles Tausend Silberlinge auf der Hand hätte, so werde ich doch nicht den Königssohn antasten. Denn der König befahl dir, Abisai und Ittai, vor unseren Ohren also: \'Habt mir acht auf den jungen Mann Absalom!\'',
        13: 'Oder sollte ich mit Gefahr meines Lebens Ungehorsam üben - dem König bleibt ja nichts verborgen -, du selbst trätest beiseite."',
        14: 'Da sprach Joab: "Mitnichten! Ich würde dich verteidigen." Da nahm er einen Dreizack in die Hand und stieß ihn Absalom ins Herz. Noch lebte er inmitten der Eiche.',
        15: 'Da traten zehn Diener herzu, Joabs Waffenträger, und schlugen Absalom vollends tot.',
        16: 'Dann stieß Joab in das Horn, und das Volk ließ von der Verfolgung Israels. Denn Joab schonte das Volk.',
        17: 'Dann nahmen sie Absalom, warfen ihn im Wald in eine große Grube und türmten einen mächtigen Steinwall über ihn. Ganz Israel aber war geflohen, jeder in sein Zelt.',
        18: 'Absalom aber hatte schon bei Lebzeiten ein Steinmal geholt und es im Königstal aufgestellt. Denn er hatte gesagt: "Ich habe keinen Sohn, um meinen Namen im Andenken zu erhalten." So nannte er das Steinmal nach seinem Namen. Daher heißt es "Absaloms Denkmal" bis auf diesen Tag.',
        19: 'Sadoks Sohn Achimaas aber sprach: "Ich könnte hinlaufen und dem König Botschaft bringen, daß der Herr ihm gegen seine Feinde geholfen hat."',
        20: 'Da sprach Joab zu ihm: "Du bist heute nicht der Mann für solche Botschaft. Ein andermal bring Botschaft! Aber am heutigen Tag darfst du keine bringen, da doch des Königs Sohn tot ist."',
        21: 'Dann sprach Joab zu dem Kuschiten: "Geh und melde dem König, was du gesehen!" Da verneigte sich der Kuschite vor Joab und lief weg.',
        22: 'Da redete Sadoks Sohn Achimaas nochmals Joab an: "Mag kommen, was will, ich möchte doch gern dem Kuschiten nachlaufen." Da sprach Joab: "Warum willst du, mein Sohn, laufen? Für dich gibt\'s keinen Botenlohn."',
        23: 'Er sprach: "Mag kommen, was will, ich laufe hin." Da sagte er zu ihm: "Lauf!" Da lief Achimaas den Weg durch die Aue und überholte den Kuschiten.',
        24: 'David aber saß eben im Doppeltor. Und der Wächter stieg auf das Tordach an der Mauer. Als er seine Augen erhob, sah er einen Mann allein daherlaufen.',
        25: 'Da rief der Wächter und meldete es dem König. Da sprach der König: "Ist er allein, dann bringt er gute Botschaft." Jener aber lief und kam immer näher.',
        26: 'Da sah der Wächter einen zweiten Mann laufen. Dies rief der Wächter dem Torwart zu und sprach: "Noch ein Mann läuft daher." Der König sprach: "Auch er bringt gute Botschaft."',
        27: 'Da sprach der Wächter: "Soviel ich sehe, gleicht des ersten Gangart der des Sadoksohnes Achimaas." Da sprach der König: "Das ist ein wackerer Mann. Er kommt mit froher Botschaft."',
        28: 'Da rief Achimaas und sprach zum König: "Heil!" Dann warf er sich vor dem König mit dem Angesicht zu Boden und sprach: "Gepriesen sei der Herr, dein Gott, der die Männer preisgegeben, die ihre Hand gegen meinen Herrn, den König, erhoben haben!"',
        29: 'Der König fragte:"Ist heil der junge Mann Absalom?" Achimaas sagte: "Ich habe wildes Getümmel gesehen, als des Königs Diener Joab schon deinen Sklaven absandte, aber ich weiß nicht, was es gegeben hat."',
        30: 'Da sprach der König: "Tritt beiseite und stell dich hierher!" Er trat beiseite und stand da,',
        31: 'als der Kuschite kam. Und der Kuschite sprach: "Mein Herr, der König, lasse sich gute Kunde melden! Denn der Herr hat dir heute geholfen gegen alle, die sich gegen dich empört haben."',
        32: 'Da fragte der König den Kuschiten: "Ist heil der junge Mann Absalom?" Da sprach der Kuschite: "Mögen dem jungen Manne im Unglück gleich werden die Feinde meines Herrn, des Königs, und alle, die sich gegen dich erhoben!"',
    },
    19: {
        1: 'Da erbebte der König, ging in des Tores Obergemach und weinte. Im Gehen rief er: "Mein Sohn Absalom! Mein Sohn! Mein Sohn Absalom! Wäre ich an deiner Statt gestorben! Absalom, mein Sohn! Mein Sohn!"',
        2: 'Da ward es Joab gemeldet: "Der König weint und trauert um Absalom."',
        3: 'Da ward der Sieg an jenem Tage zur Trauer für das ganze Volk, weil das Volk an jenem Tage hörte: "Der König grämt sich um seinen Sohn."',
        4: 'Und das Volk stahl sich an jenem Tage in die Stadt, wie sich das Volk hereinstiehlt, wenn es durch Flucht aus der Schlacht mit Schimpf bedeckt ist.',
        5: 'Der König aber hatte sich das Gesicht verhüllt. Und der König schrie laut auf: "Mein Sohn Absalom! Absalom, mein Sohn! Mein Sohn!"',
        6: 'Da ging Joab zum König und sprach: "Du benimmst dich heute schändlich vor deinen Dienern, die heute dir, deinen Söhnen und Töchtern, deinen Weibern und Nebenweibern das Leben gerettet haben.',
        7: 'Du liebst deine Hasser und hassest deine Freunde. Denn du zeigst heute, daß Fürsten und Diener dir nichts sind. Heute bin ich überzeugt: Wäre Absalom am Leben und wir wären heute alle tot, dir wäre es ganz recht.',
        8: 'Nun aber auf! Tritt hinaus und sprich freundlich zu deinen Dienern! Denn ich schwöre beim Herrn: Gehst du nicht hinaus, dann bleibt kein Mann diese Nacht bei dir. Und das wäre für dich ein Unglück, schlimmer als alles, was über dich von deiner Jugend bis jetzt gekommen ist."',
        9: 'Da erhob sich der König und setzte sich an das Tor. Dem Kriegsvolke aber war gemeldet worden: "Der König sitzt im Tor." Da kam alles Volk vor den König, Israel aber floh, jeder in seine Zelte.',
        10: 'Das ganze Volk aber lag in Hader. In allen Städten Israels hieß es: "Der König hat uns aus der Philister Hand gerettet. Nun aber ist er aus dem Lande vor Absalom geflohen.',
        11: 'Absalom aber, den wir uns gesalbt, ist im Kampfe gefallen. Nun denn! Was zögert ihr, den König zurückzuführen?"',
        12: 'Da sandte der König David zu den Priestern Sadok und Ebjatar und ließ sagen: "Sagt den Ältesten Judas: \'Warum wollt ihr hintan sein, den König in sein Haus zurückzuführen?\'" Das Gerede von ganz Israel war nämlich schon zum König in sein Haus gedrungen.',
        13: '"\'Ihr seid meine Brüder, ihr mein Fleisch und Bein. Warum wollt ihr hintan sein, den König zurückzuführen?\'',
        14: 'Und zu Amasa sollt ihr sagen: \'Bist du nicht mein Fleisch und Bein? So und so tue mir Gott, wenn du nicht bei mir fein alle Zeiten Oberfeldherr wirst an Joabs Stelle!\'"',
        15: 'Da wandte sich der Sinn der judäischen Mannschaft insgesamt, daß sie einmütig zum König sandten: "Kehre mit all deinen Dienern zurück!"',
        16: 'Der König kehrte nun zurück und kam an den Jordan. Juda aber kam nach dem Gilgal, dem König entgegen, um den König über den Jordan zu fahren.',
        17: 'Da eilte der Benjaminite Simei, Geras Sohn, aus Bachurim herbei und zog mit Judas Mannschaft hinab, dem König David entgegen.',
        18: 'Bei ihm waren tausend Mann aus Benjamin. Auch Siba, der Diener des Hauses Saul, hatte mit seinen fünfzehn Söhnen und zwanzig Sklaven den Jordan im Angesichte des Königs durchwatet.',
        19: 'Und das Fährboot fuhr hinüber, um das Königshaus überzuführen und zu tun, was ihm gefiele. Da warf sich Geras Sohn Simei vor dem König nieder, als er über den Jordan gefahren war.',
        20: 'Und er sprach zum König: "Möge mein Herr mir keine Schuld mehr anrechnen und nicht dessen gedenken, was dein Sklave an jenem Tage verbrochen hat, da mein Herr, der König, aus Jerusalem gezogen, daß es sich der König zu Herzen nähme!',
        21: 'Dein Knecht weiß, daß ich mich vergangen habe. Aber ich komme heute als erster vom ganzen Josephshause meinem Herrn, dem König, entgegen."',
        22: 'Da hub Serujas Sohn Abasai an und sprach: "Sollte dafür Simei nicht den Tod leiden? Er hat dem Gesalbten des Herrn geflucht."',
        23: 'Da sprach David: "Was habe ich mit euch, ihr Serujasöhne, zu tun, daß ihr mir heute zum Versucher werdet? Sollte heute jemand in Israel getötet werden? Weiß ich denn nicht, daß ich jetzt erst König über Israel bin?"',
        24: 'Und der König sprach zu Simei: "Du sollst nicht sterben!" Und der König schwur es ihm zu.',
        25: 'Auch Sauls Enkel Mephiboset ging dem König entgegen. Er hatte aber sein Haupthaar nicht gepflegt noch seinen Bart geordnet und seine Kleider nicht gewaschen seit dem Tage, da der König fortgegangen, bis zu dem Tage, da er im Frieden nach Jerusalem zog.',
        26: 'Als er dem König, Jerusalem zu, begegnete, fragte ihn der König: "Warum bist du nicht mit mir gegangen, Mephiboset?"',
        27: 'Er sprach: "Mein Herr und König! Mich hat mein Diener betrogen. Denn dein Sklave hatte gesagt: \'Ich will mir den Esel satteln, daß ich auf ihm reite und mit dem König ziehe.\' Dein Sklave ist ja lahm.',
        28: 'Er aber verleumdete deinen Sklaven bei meinem Herrn, dem König. Aber mein Herr, der König, gleicht einem Engel Gottes. Tu, was dir beliebt!',
        29: 'Mein ganzes Vaterhaus ist ja bei meinem Herrn, dem König, dem Tode verfallen, du aber setztest deinen Sklaven unter deine Tischgäste. Was für ein Recht hätte ich noch, mich beim König zu beklagen?"',
        30: 'Da sprach der König zu ihm: "Warum machst du soviel Worte? Ich sage: Du und Siba sollt das Landgut teilen!"',
        31: 'Da sprach Mephiboset zum König: "Er behalte sogar das Ganze, wenn mein Herr, der König, heil in sein Haus einzieht!"',
        32: 'Auch der Gileadite Barzillai war von weither gekommen; auch er setzte mit dem König über den Jordan, ihn über den Jordan zu begleiten.',
        33: 'Barzillai aber war sehr alt, ein Achtzigjähriger. Er hatte den König bei seinem Aufenthalt zu Machanaim versorgt. Denn er war ein sehr vermöglicher Mann.',
        34: 'Da sprach der König zu Barzillai: "Geh du mit mir hinüber, und ich sorge für dich bei mir zu Jerusalem!"',
        35: 'Da sprach Barzillai zum König: "Wieviel sind die Tage meiner Lebensjahre, daß ich mit dem König nach Jerusalem zöge?',
        36: 'Achtzig Jahre bin ich jetzt alt. Kann ich da noch Gutes und Schlechtes unterscheiden? Schmeckt deinem Sklaven, was ich esse und trinke? Höre ich noch die Stimme der Sänger und Sängerinnen? Wozu fiele dein Sklave meinem Herrn, dem König, noch zur Last?',
        37: 'Kaum kann dein Sklave den König über den Jordan begleiten. Aber warum vergilt mir der König also?',
        38: 'Dein Sklave möchte lieber umkehren, daß ich in meiner Stadt bei meines Vaters und meiner Mutter Grab stürbe! Aber dein Sklave Kimham möchte mit meinem Herrn, dem König, hinüberziehen! Tu ihm, was dir gut dünkt!"',
        39: 'Da sprach der König: "So ziehe Kimham mit mir hinüber! Ich tue ihm, was dir gefällt; aber auch alles, was du von mir wünschst, werde ich dir tun."',
        40: 'Nun setzte alles Volk über den Jordan. Auch der König setzte über. Da küßte der König den Barzillai und segnete ihn. Und er kehrte heim.',
        41: 'Dann zog der König nach dem Gilgal; auch Kimham zog mit ihm. So führte der ganze judäische Heerbann den König hinüber, ebenso die Hälfte des Volkes Israel.',
        42: 'Dann kam der ganze israelitische Heerbann zum König. Und sie sprachen zum König: "Warum haben dich unsere Brüder entführt, Judas Heerbann? Sie brachten den König samt seinem Hause und alle Mannen Davids bei ihm über den Jordan."',
        43: 'Da erwiderten alle Mannen Judas der Mannschaft Israels: "Der König ist mit uns verwandt. Warum bist du deshalb zornig? Haben wir auf des Königs Kosten gespeist? Hat man uns aufgetragen?" Da hob Israels Mannschaft an und sprach zu der Mannschaft Judas: "Ich habe am König zehn Teile, und auch an David bin ich dir voraus. Weshalb achtest du mich gering? Und stand es nicht mir zuerst zu, meinen König zurückzuführen?" Aber die Rede der Mannschaft Judas war durchschlagender als die der Mannschaft Israels.',
    },
    20: {
        1: 'Dort aber war zufällig ein nichtswürdiger Mann namens Seba, Bikris Sohn, ein Benjaminite. Er stieß in das Horn und rief: "Wir haben an David keinen Teil und keinen Anteil an dem Isaisohne. Israel, ein jeglicher zu seinen Zelten!"',
        2: 'Da fiel Israels gesamte Mannschaft von David zum Bikrisohne Seba ab. Judas Mannschaft aber scharte sich um ihren König vom Jordan bis Jerusalem.',
        3: 'So kam David in sein Haus zu Jerusalem. Da nahm der König die zehn Nebenweiber, die er zur Bewachung des Hauses dagelassen hatte und brachte sie in ein besonderes Haus und versorgte sie. Er aber kam nicht mehr zu ihnen. So lebten sie bis zu ihrem Todestage abgeschlossen als lebenslängliche Witwen.',
        4: 'Dann sprach der König zu Amasa: "Entbiete mir Judas Mannschaft in drei Tagen! Du selbst stelle dich hier ein!"',
        5: 'Da ging Amasa, Juda aufzubieten. Er verzog sich aber über die Frist, die er ihm gesetzt hatte.',
        6: 'Da sprach David zu Abisai: "Nun wird Seba für uns noch schlimmer als Absalom. Nimm jetzt deines Herrn Diener und setze ihm nach, daß er nicht feste Städte gewinne und unsere Quellen wegnehme!"',
        7: 'So zogen hinter ihm Joabs Leute einher, ebenso die Bogenschützen und die Schildträger und alle anderen Krieger. Sie zogen aus Jerusalem, den Bikrisohn Seba zu verfolgen.',
        8: 'Sie waren eben bei dem großen Stein in Gibeon. Da ging Amasa ihnen voraus. Joab aber war mit einem langen Gewande angetan, und darin war ein Schwert, das mit der Scheide an seine Hüfte geknüpft war. Er zog es heraus, verbarg es aber.',
        9: 'Da fragte Joab Amasa: "Geht es dir gut, mein Bruder?" Dabei faßte Joab mit der Rechten Amasa am Bart, ihn zu küssen.',
        10: 'Amasa aber beachtete nicht das Schwert in Joabs Hand. Und so stieß er ihn damit in den Leib. Da ließ er seine Eingeweide auf den Boden fallen. Jener aber brauchte ihm keinen zweiten Stoß zu geben. Er starb. Joab aber und sein Bruder Abisai setzten Bikris Sohne Seba weiter nach.',
        11: 'Einer von Joabs Knechten aber war zu ihm getreten und sprach: "Wer es mit Joab und David hält, folge Joab!"',
        12: 'Amasa aber wälzte sich im Blute mitten auf der Straße. Als die Mannschaft sah, wie alles Volk stehenblieb, schob sie Amasa von der Straße auf das Feld und warf auch einen Mantel über ihn; denn sie sah, daß jeder, der an ihm vorüberkam, stehenblieb.',
        13: 'Als sie ihn von der Straße weggeschafft hatten, folgte jedermann Joab, um Seba, den Bikrisohn, zu verfolgen.',
        14: 'Und er durchzog alle Stämme Israels bis Abel Beth Maaka. Und alle Banden sammelten sich und folgten ihm.',
        15: 'So kamen sie, belagerten ihn zu Abel Beth Maaka und schütteten gegen die Stadt einen Wall auf, der auf den Festungsgraben kam. Und das ganze Volk bei Joab unterwühlte die Mauer, um sie zu stürzen.',
        16: 'Da rief ein weises Weib aus der Stadt: "Hört! Hört! Sagt doch Joab: \'Komm hierher! Ich möchte dich sprechen.\'"',
        17: 'Und er näherte sich ihr. Da fragte das Weib: "Bist du Joab?" Er sagte: "Ja!" Da sprach sie zu ihm: "Höre deiner Sklavin Worte!" Er sprach: "Ich höre."',
        18: 'Sie sprach dann also: "Man pflegte in alter Zeit zusagen: \'Man frage über Abel nach\', dann sagt man also:',
        19: '\'Ich bin die Friedfertigste und Getreueste in Israel.\' Du aber suchst eine Mutterstadt in Israel zu vernichten. Weshalb vernichtest du des Herrn Eigentum?"',
        20: 'Da hub Joab an und sprach: "Ferne, ferne sei dies von mir! Ich will nichts verderben und nichts vernichten.',
        21: 'Nicht so ist es, sondern ein Mann vorn Gebirge Ephraim, namens Seba, Bikris Sohn, hat seine Hand gegen den König David erhoben. Ihn allein liefert aus, dann ziehe ich von der Stadt ab." Da sprach das Weib zu Joab: "Sein Kopf soll dir über die Mauer zugeworfen werden."',
        22: 'Das Weib kam nun mit seiner Klugheit zum ganzen Volk. Da hieben sie Bikris Sohn Seba den Kopf ab und warfen ihn Joab zu. Da stieß er in das Horn, und sie lösten sich auf und zogen von der Stadt weg, jeder zu seinen Zelten, Joab aber zog heim zum König nach Jerusalem.',
        23: 'Joab blieb nun Befehlshaber über das ganze Heer Israels, Benaja, Jojadas Sohn, aber über die Bogenschützen und Schildträger',
        24: 'und Adoram über den Frondienst. Josaphat, Achiluds Sohn, war Kanzler.',
        25: 'Seja war Schreiber, Sadok und Ebjatar waren Priester.',
        26: 'Auch der Jairite Ira war bei David Priester.',
    },
    21: {
        1: 'In Davids Tagen war drei Jahre lang, Jahr für Jahr, eine Hungersnot. Da suchte David das Antlitz des Herrn. Der Herr aber sprach: "Auf Saul und seinem Haus ruht eine Blutschuld, weil er die Gibeoniten getötet hat."',
        2: 'Da berief der König die Gibeoniten und sprach zu ihnen. (Die Gibeoniten aber gehörten nicht zu den Söhnen Israels, sondern zu dem Reste der Amoriter. Doch die Söhne Israels hatten sich ihnen eidlich verpflichtet. Saul aber suchte in seinem Eifer für die Söhne Israels und Juda sie auszurotten.)',
        3: 'Da sprach David zu den Gibeoniten: "Was soll ich für euch tun? Womit Sühne schaffen? Segnet doch des Herrn Eigentum!"',
        4: 'Da sprachen die Gibeoniten zu ihm: "Wir wollen kein Silber und Gold von Saul und seinem Hause. Auch im übrigen Israel gibt es keinen Mann, dessen Tod wir fordern." Da sprach er: "Was ihr sagt, tue ich für euch."',
        5: 'Da sprachen sie zum König: "Der Mann, der uns aufgerieben und auf unsere Vernichtung gesonnen, daß wir im ganzen Bereich Israels nicht mehr bestünden:',
        6: 'aus seinen Söhnen soll man uns sieben Männer geben, daß wir sie dem Herrn aussetzen zu Gibea Sauls, des vom Herrn Erwählten!" Da sprach der König: "Ich gebe Sie."',
        7: 'Der König aber verschonte Mephiboset, den Sohn des Saulssohnes Jonatan, wegen des Herrnschwures, der zwischen David und Sauls Sohn Jonatan bestand.',
        8: 'So nahm der König der Rispa, Ajas Tochter, beide Söhne, die sie Saul geboren hatte, Armoni und Mephiboset, sowie der Merab, Sauls Tochter, fünf Söhne, die sie dem Mecholatiter Adriel, Barzillais Sohn, geboren hatte.',
        9: 'Diese gab er den Gibeoniten. Und sie setzten sie auf dem Berge vor dem Herrn aus. So kamen die Sieben zusammen um. Und zwar starben sie in den Tagen der Gerstenernte, in den ersten Tagen, zu Beginn der Gerstenernte.',
        10: 'Da nahm Ajas Tochter Rispa das Trauergewand und breitete es sich auf den Felsen, vom Beginn der Gerstenernte, bis Wasser vom Himmel auf sie floß. So hatte sie es verhütet, daß des Himmels Vögel bei Tag und des Feldes Tiere bei Nacht über sie herfielen.',
        11: 'Da ward David gemeldet, was Rispa, Ajas Tochter und Sauls Nebenweib, getan.',
        12: 'Da ging David hin und holte die Gebeine Sauls und die seines Sohnes Jonatan von den Bürgern in Jabes Gilead. Sie hatten sie vom Marktplatz in Betsean entführt, wo sie die Philister aufgehängt hatten an jenem Tage, als sie Saul am Gilboa schlugen.',
        13: 'So brachte er Sauls und seines Sohnes Jonatan Gebeine von dort weg. Dann sammelte man die Gebeine der Ausgesetzten',
        14: 'und begrub sie mit Sauls und seines Sohnes Jonatan Gebeinen im Lande Benjamin zu Sela im Grabe seines Vaters Kis. So tat man alles, was der König befohlen hatte, und Gott ward danach dem Lande hold gestimmt. -',
        15: 'Da war wieder Krieg zwischen den Philistern und Israel. David zog mit seinen Dienern hinab, und sie kämpften mit den Philistern. David aber ward müde.',
        16: 'Da nahm ihn Benob gefangen. Dieser gehörte zu den Kindern des Akis, und sein Speer wog 300 Sekel Erz; er hatte erst jüngst den Gurt angelegt. Und schon dachte er daran, David zu erschlagen.',
        17: 'Da kam ihm Serujas Sohn Abisai zu Hilfe. Und er schlug den Philister tot. Damals beschworen Davids Leute ihn: "Du darfst nicht mehr mit uns in den Kampf ziehen, daß du nicht Israels Leuchte verlöschest!"',
        18: 'Hernach war wieder Krieg zu Gob mit den Philistern. Damals schlug der Chusatiter Sibkai den Saph von den Kindern des Akis.',
        19: 'Nochmals war ein Kampf mit den Philistern zu Gob. Da schlug Jairs Sohn Elchanan, ein Weber aus Bethlehem, den Gatiter Goliat, dessen Speerschaft einem Weberbaume glich.',
        20: 'Nochmals war ein Kampf bei Gat. Da war ein Kriegsmann, der je sechs Finger an den Händen und je sechs Zehen an den Füßen hatte, zusammen vierundzwanzig, und der ebenfalls von Akis stammte.',
        21: 'Er höhnte Israel. Da schlug ihn Jonatan, der Sohn Simis, des Bruders Davids.',
        22: 'Diese Vier stammten von Akis zu Gat ab, und sie fielen durch Davids und seiner Diener Hand.',
    },
    22: {
        1: 'David dichtete für den Herrn die Worte dieses Liedes, zu der Zeit, da ihn der Herr aus der Hand aller seiner Feinde und besonders aus der des Saul befreite.',
        2: 'Er sprach: "Ein Fels ist mir der Herr und eine Rettungsburg,',
        3: 'mein Gott mein Hort, wo ich mich berge, mein Schild, mein sieghaft Horn und meine Feste.',
        4: "'Gepriesen sei der Herr!' das einzig rufe ich und bin von meinen Feinden schon erlöst.",
        5: 'Schon hatten Todesfluten mich umgeben; mich schreckten des Verderbens Ströme.',
        6: 'Der Hölle Stricke hatten mich umschlungen; des Todes Schlingen überraschten mich.',
        7: 'Da rief ich in der Not zum Herrn und schrie zu meinem Gott um Hilfe. Er hört in seinem Tempel meine Stimme, und mein Geschrei dringt ihm zu Ohren.',
        8: 'Die Erde schütterte und bebte; des Himmels Festen zitterten und wankten. Er war ergrimmt.',
        9: 'Aufquoll aus seiner Nase Rauch; aus seinem Munde sprühte Feuer, und eine Glut ward von ihm ausgesprüht.',
        10: 'Den Himmel neigte er und fuhr herab, tief Dunkel unter seinen Füßen.',
        11: 'Er fuhr auf einem Cherub, flog einher, auf Windesflügeln schwebend.',
        12: 'Zur Hülle nahm er Dunkel rings um sich und Wasserflut und dicht Gewölk.',
        13: 'An seiner Nähe Glanz entzündeten sich Feuerströme.',
        14: 'Der Herr im Himmel donnerte; der Höchste ließ die Stimme dröhnen.',
        15: 'Und Pfeile schoß er ab nach allen Seiten und warf die Blitze hin in regelloser Wahl.',
        16: 'Des Meeres Betten zeigten sich; der Erde Gründe wurden bloßgelegt vor dem Gedroh des Herrn, vor seinem Zornesschnauben.',
        17: 'Herab griff er und faßte mich und zog mich aus gewaltigen Gewässern,',
        18: 'entriß mich meinen argen Feinden und meinen überlegnen Hassern,',
        19: 'die mich an meinem Unglückstage überfielen. So wurde mir der Herr zur Stütze.',
        20: 'Er führte mich hinaus ins Freie, befreite mich, weil er an mir Gefallen fand.',
        21: 'Der Herr vergalt mir so nach meiner Rechtlichkeit und lohnte mir nach meiner Hände Reinheit.',
        22: 'Denn immer halte ich des Herren Wege und frevle nimmer gegen meinen Gott,',
        23: 'denn alle seine Rechte habe ich vor Augen und lasse seine Satzungen nicht aus dem Sinn.',
        24: 'Ich habe ihm mich ungeteilt ergeben und mich vor meiner Lieblingssünde wohl gehütet.',
        25: 'Darum vergalt der Herr mir auch nach meiner Rechtlichkeit, nach meiner ihm bekannten Reinheit.',
        26: 'Du bist dem Holden hold, dem Treugesinnten treugesinnt,',
        27: 'verfährst mit Reinen rein, doch böse mit dem Bösen.',
        28: 'Dem armen Volke stehst Du bei; doch auf den Stolzen senkst Du Deine Augen.',
        29: 'Du bist mein Licht, Du Herr, Du Herr, mein Gott, der meine Finsternis erhellt.',
        30: 'Mit Dir erstürme ich die Wälle; und Mauern überspringe ich mit meinem Gott.',
        31: 'Truglos ist Gottes Weg; geläutert ist das Wort des Herrn, ein Schild für alle, die zu ihm sich flüchten.',
        32: 'Denn wer ist Gott, wenn nicht der Herr? Wer sonst ein Hort als unser Gott?',
        33: 'Das ist der Gott, der meine feste Zuflucht ist, der unbehindert seines Weges eilt,',
        34: 'der gleich den Rehen meine Füße macht und mich auf meine Höhen stellt,',
        35: 'der meine Hände kämpfen lehrt und meine Arme eherne Bogen spannen läßt.',
        36: 'Du reichst mir Deinen Siegesschild, und Deine Rechte stützet mich, und Deine Stärkung macht mich kräftig.',
        37: 'Und meinen Schritten gibst Du weiten Raum, und meine Knöchel wanken nicht.',
        38: 'Ich setze meinen Feinden nach und greife sie und kehre nicht zurück, bis daß ich sie vernichtet habe.',
        39: 'Ich schlage sie, daß sie sich nimmermehr erheben, und daß sie unter meinen Füßen liegen.',
        40: 'Du gürtest mich mit Kraft zum Kampfe, und meine Gegner beugst Du unter mich.',
        41: 'Und meiner Feinde Rücken zeigst Du mir, daß ich vertilge meine Hasser.',
        42: 'Sie rufen - niemand hilft - zum Herrn; er hört sie nicht.',
        43: 'Und ich zermalme sie wie Staub vorm Winde; zerstampfe sie gleich Gassenkot.',
        44: 'Du rettest mich vor Tausenden von Kriegervölkern; zum Haupt von Heiden machst Du mich; mir unbekannte Leute dienen mir.',
        45: 'Des Auslands Söhne schmeicheln mir; aufs Hörensagen leisten sie mir schon Gehorsam,',
        46: 'und andere Fremdlinge verschwinden und sitzen zitternd in Verstecken.',
        47: 'Lebendig ist der Herr und hochgepriesen als mein Hort, und als mein hilfereicher Gott steht hoch er da.',
        48: 'Gott, der Du mir verhilfst zur Rache und Völker mir zu Füßen legst,',
        49: 'der Du vor meinen Feinden mich errettest, Du machst mich fürder meinen Gegnern unerreichbar und rettest mich vor Wüterichen.',
        50: 'dafür lobpreise ich Dich bei den Heiden, Herr, und singe also Deinem Namen:',
        51: '\'Heilvoller Turm für seinen König, der David, den er salbte, Huld erweist und seinem Stamme ewiglich.\'"',
    },
    23: {
        1: 'Dies sind Davids letzte Worte, ein Ausspruch des Isaisohnes David und ein Ausspruch des Mannes, der als Gesalbter des Jakobsgottes und als Sänger der Lieder Israels dastand:',
        2: 'Es spricht der Geist des Herrn durch mich; auf meiner Zunge ist sein Wort.',
        3: "Gesprochen hat der Gott von Israel. Gesprochen hat zu mir der Fels von Israel: 'Wer über Menschen herrscht gerecht, von Gottesfurcht erfüllt, als Herrscher,",
        4: "der gleicht dem Licht am Morgen, am wolkenlosen Morgen, wenn hell die Sonne strahlt, die Gräser aus dem Boden sprossen läßt.'",
        5: "Steht also nicht mein Haus zu Gott? - Hat er doch einen ewig gültigen Bund mit mir geschlossen, der festgestellt in allem und gesichert ist. - Denn all mein Streben und mein Wünschen, läßt er's denn nicht gelingen?",
        6: 'Die Frevler aber sind wie lose Dornen alle zumal nicht in die Hand zu nehmen.',
        7: 'Wer auf sie trifft, der schlägt mit Eisen, schlägt mit dem Lanzenschaft darein, sie werden ohne Widerstand verbrannt."',
        8: 'Das sind die Namen der Helden, die David hatte: des Chakmoni Sohn Josabam, das Haupt der Drei. Er stritt mit seinem Speere gegen 800 Unreine auf einmal.',
        9: 'Nach ihm kommt der Achochiter Eleazar, Dodis Sohn; er war unter den drei Kriegern bei David; am Blutsteinfelsen ging er gegen die Philister los. Diese hatten sich dort zum Kampfe gesammelt. Da zog sich Israels Mannschaft zurück.',
        10: 'Er aber hielt stand und hieb auf die Philister ein, bis seine Hand ermattete und seine Hand am Schwerte kleben blieb. Und der Herr schaffte an jenem Tage einen großen Sieg; das Volk zog ihm nun nach, aber nur um zu plündern.',
        11: 'Nach ihm kommt der Harariter Samma, des Age Sohn. Einst sammelten sich die Philister in Lechi. Dort war ein Feld voller Garben. Da aber das Volk vor den Philistern floh,',
        12: 'Stellte er sich mitten in das Feld, rettete es und schlug die Philister, und der Herr schaffte einen großen Sieg.',
        13: 'Drei von den dreißig Hauptleuten stiegen hinab und kamen zu dem Felsen, zu David in die Höhle von Adullam. Die Philisterschar aber lagerte in der Rephaimebene.',
        14: 'David war damals in der Feste, der Philisterposten aber in Bethlehem.',
        15: 'Da spürte David ein Gelüste und sprach: "Wer holt mir Trinkwasser aus dem Brunnen in Bethlehem am Tor?"',
        16: 'Da schlugen sich die drei Krieger durch das Philisterlager, schöpften aus dem Brunnen in Bethlehem am Tor und brachten es David. Aber er wollte nicht mehr trinken, sondern spendete es dem Herrn.',
        17: 'Er sprach: "Ferne sei es mir, Herr, daß ich solches tue! Ist es doch Blut der Männer, die unter Lebensgefahr hingingen." Und er wollte es nicht trinken. So hatten die drei Helden getan.',
        18: 'Der Serujasohn Abisai, Joabs Bruder, war das Haupt der Dreißig. Er schwang seinen Speer gegen 300 Unreine und war bei den Dreien angesehen.',
        19: 'Er wurde also von den Dreien ausgezeichnet, und so ward er bei ihnen Hauptmann. Aber an die Drei reichte er nicht heran.',
        20: 'Des Jojada Sohn Benaja war der Sohn eines richtigen, tatenreichen Mannes aus Kabseel. Er selber hatte Moabs beide Kämpen erschlagen. Auch er war hinabgestiegen und hatte den Löwen mitten im Brunnen erschlagen, als Schnee fiel.',
        21: 'Auch hatte er einen Ägypter erschlagen, einen riesigen Mann. Der Ägypter hatte einen Speer in der Hand. Er aber ging mit einem Stock auf ihn los, entriß dem Ägypter die Lanze und tötete ihn mit seinem eigenen Speer.',
        22: 'Dies hatte Benaja, Jojadas Sohn, getan. Auch er hatte einen Namen bei den drei Helden.',
        23: 'Unter den Dreißig hatte er sich ausgezeichnet. Aber an die Drei reichte er nicht heran. David stellte ihn bei seiner Leibwache an.',
        24: 'Unter den Dreißig waren Joabs Bruder Asahel, ferner Dodos Sohn Elchanan aus Bethlehem,',
        25: 'der Charoditer Samma, der Charoditer Elika,',
        26: 'der Paltiter Cheles, der Tekoiter Ira, des Ikkes Sohn,',
        27: 'der Anatotiter Abiezer, der Chusatiter Mebunnai,',
        28: 'der Achochiter Salmon, der Netophatiter Maharai,',
        29: 'der Netophatiter Cheleb, Baanas Sohn Ittai aus Gibea in Benjamin,',
        30: 'der Piratotiter Benaja, Hiddai aus Nachale Gaas,',
        31: 'der Arbatiter Abialbon, der Barchumiter Azmawet,',
        32: 'der Saalboniter Eljachba, die Söhne Jasens, Jonatan,',
        33: 'der Harariter Samma, der Arariter Achiam, Sarars Sohn,',
        34: 'der Maakatiter Eliphelet, Achasbais Sohn, der Giloniter Eliam, Achitophels Sohn,',
        35: 'der Karmeliter Chesro, der Arbiter Paarai,',
        36: 'Igal, Natans Sohn aus Soba, der Gaditer Bani,',
        37: 'der Ammoniter Selek, der Beerotiter Nakarai sowie des Serujasohnes Joab Waffenträger,',
        38: 'der Itriter Ira, der Itriter Gareb',
        39: 'und Urias, der Chittiter. Zusammen siebenunddreißig.',
    },
    24: {
        1: 'Nochmals zürnte der Herr über Israel. Und so reizte er David gegen Israel durch den Befehl: "Auf! Zähle Israel und Juda!"',
        2: 'Da sprach der König zu Joabs Heerführern, die bei ihm waren: "Durchwandert alle Stämme Israels von Dan bis Beerseba und zählt das Volk, daß ich die Zahl des Volkes erfahre!"',
        3: 'Da sprach Joab zum König: "Mag der Herr, dein Gott, das Volk, wie es ist, hundertfach vermehren, und mag mein Herr, der König, dies selbst erleben! Aber warum verlangt dies mein Herr, der König?"',
        4: 'Aber des Königs Befehl zwang Joab und die Heerführer. So gingen Joab und die Heerführer vom König weg, das Volk Israel zu zählen.',
        5: 'Sie überschritten den Jordan und machten sich an die Arbeit in Aroër, rechts von der Stadt, im Bachtale, gegen Gad und Jazer hin.',
        6: 'So kamen sie nach dem Gilead und in das Land unter dem Hermon. Dann kamen sie nach Dan und in Galiläas Umkreis nach Sidon zu.',
        7: 'Dann kamen sie zur Festung von Tyrus sowie zu allen Chiwiter- und Kanaaniterstädten. Dann zogen sie nach Judas Südland, nach Beerseba.',
        8: 'So durchstreiften sie das ganze Land und kamen nach neun Monaten und zwanzig Tagen nach Jerusalem zurück.',
        9: 'Da gab Joab die Zahl aus der Volkszählung dem Könige an: "Israel zählte 800.000 an waffenfähigen, schwertgerüsteten Mannen und Juda nach seiner Mannschaft 500.000."',
        10: 'David aber schlug das Gewissen nach der Volkszählung. Und so sprach David zum Herrn: "Ich habe schwer gesündigt durch das, was ich getan. Nun aber, Herr, vergib die Schuld Deines Sklaven. Denn ich habe töricht gehandelt."',
        11: 'Als David am Morgen aufstand, war das Wort des Herrn an den Propheten Gad, Davids Seher, also ergangen:',
        12: '"Auf! Sprich zu David: \'So spricht der Herr: Ich lege dir dreierlei vor: Eins wähle dir davon, daß ich es dir antue!\'"',
        13: 'Da ging Gad zu David und verkündete es ihm. Er sprach zu ihm: "Entweder für dich drei Jahre Hungersnot in deinem Land oder drei Monate Flucht vor deinem Feind, wenn er dich verfolgt, oder drei Tage Pest in deinem Land? Nun besinne dich und sieh zu, was ich dem bescheiden soll, der mich sendet!"',
        14: 'Da sprach David zu Gad: "Mir ist sehr bange. Laßt uns lieber in des Herrn Hand fallen! Denn sein Erbarmen ist groß. Aber in Menschenhand möchte ich nicht fallen."',
        15: 'So schickte der Herr eine Pest über Israel vom Morgen bis zum Vormittag. Und vom Volke starben 70.000 Mann von Dan bis Beerseba.',
        16: 'Und der Engel des Herrn streckte seine Hand gegen Jerusalem aus, es zu vernichten. Da reute den Herrn das Unheil, und er gebot dem Engel, der unter dem Volke würgte: "Genug! Zieh deine Hand jetzt ab!" Des Herrn Engel war eben bei der Tenne des Jebusiters Arauna.',
        17: 'Da sprach David zum Herrn, als er sah, wie der Engel das Volk schlug, und sagte: "Ich habe gefehlt und gesündigt. Was aber haben die Schafe getan? Deine Hand sei doch gegen mich und mein Haus!"',
        18: 'Da kam Gad zu David an jenem Tage und sprach zu ihm: "Geh hinauf und errichte dem Herrn einen Altar auf der Tenne des Jebusiters Arauna!"',
        19: 'Da ging David auf Gads Geheiß hinauf, wie ihm der Herr befohlen.',
        20: 'Arauna schaute eben aus. Da sah er den König mit seinen Dienern auf sich zukommen. So trat Arauna hinaus und neigte sein Antlitz vor dem König bis zum Boden.',
        21: 'Dann sprach Arauna: "Warum kommt mein Herr, der König, zu seinem Sklaven?" Da sprach David: "Um dir die Tenne abzukaufen und dem Herrn einen Altar zu bauen, daß die Seuche vom Volke abgewehrt werde."',
        22: 'Da sprach Arauna: "Mein Herr, der König, wolle nehmen und opfern, was ihm beliebt! Hier sind die Rinder zum Brandopfer und die Dreschwagen und das Rindergeschirr zum Holz.',
        23: 'Dies alles, o König, schenkt Arauna dem König." Ferner sprach Arauna zum König: "Der Herr, dein Gott, sei dir geneigt!"',
        24: 'Da sprach der König zu Arauna: "Nein! Ich will es von dir um Entgelt erwerben! Ich kann dem Herrn, meinem Gott, nicht Brandopfer ohne Entgelt darbringen." So kaufte David die Tenne und die Rinder für fünfzig Silberlinge.',
        25: 'Und David baute dort dem Herrn einen Altar und brachte Brand- und Mahlopfer dar. Und der Herr ward dem Lande hold gestimmt. So ward die Seuche von Israel abgewehrt.',
    },
}
